document.addEventListener('click',event=>{const b=event.target.closest('[data-pet-plan],[data-default-plan],[data-accept],[data-decline],[data-reserve],[data-assign],[data-build-project],[data-upgrade-guild],[data-buy-mat],[data-sell-mat],[data-auto-work],[data-hire],[data-decline-app],[data-rank-exam],[data-lesson],[data-roster-tab],[data-member-tab],[data-policy-hunt],[data-policy-petitions],[data-buy-rate],[data-auto-wholesale],[data-wholesale],[data-workshop-toggle],[data-send-caravan],[data-treasure-sell],[data-treasure-show],[data-invite-free],[data-watch-member]');if(!b||b.disabled)return;const d=b.dataset;
 if(d.petPlan){const p=(state.petitions||[]).find(p=>p.id===d.petPlan);if(!p)return;if(p.status==='waiting'){ui.petPlan={...ui.petPlan,[p.id]:d.planId};syncUI();}else if(dispatch('setPetition',{petitionId:p.id,plan:d.planId}))syncUI();return;}
 if(d.defaultPlan){if(dispatch('setPayoutPlan',{plan:d.planId}))syncUI();return;}
 if(d.accept){if(dispatch('acceptPetition',{petitionId:d.accept,plan:ui.petPlan?.[d.accept]||state.payoutPlan}))syncUI();return;}
 if(d.decline){if(dispatch('declinePetition',{petitionId:d.decline}))syncUI();return;}
 if(d.reserve){const p=state.petitions.find(p=>p.id===d.reserve);if(p&&dispatch('setPetition',{petitionId:p.id,reserved:!p.reserved}))syncUI();return;}
 if(d.assign){const p=state.petitions.find(p=>p.id===d.assign);if(!p)return;ui.questId=p.questId;ui.petitionId=p.id;ui.missionId=null;ui.selected.clear();ui.region=QUESTS.find(q=>q.id===p.questId)?.region||ui.region;syncUI();return;}
 if(d.buildProject){const id=d.buildProject,status=getProjectStatus(state,id);if(status.ok&&renderer?.ready&&(id==='house'||!(state.village?.[id]>0))){closeMenu();ui.buildType=null;ui.moveId=null;ui.villagePlace={projectId:id};renderer.startVillagePlacement(id==='house'?'h'+state.village.houses:id,id==='house'?'house':id);syncHUD();return;}if(dispatch('buildProject',{projectId:id})){renderer?.setState(state);syncUI();}return;}
 if(d.upgradeGuild){if(dispatch('buyUpgrade',{upgradeId:d.upgradeGuild}))syncUI();return;}
 if(d.buyMat){if(dispatch('buyMaterial',{key:d.buyMat}))syncUI();return;}
 if(d.sellMat){if(dispatch('sellMaterial',{key:d.sellMat}))syncUI();return;}
 if(d.rosterTab){ui.rosterTab=d.rosterTab;ui.memberId=null;syncUI();return;}
 if(d.memberTab){ui.memberTab=d.memberTab;syncUI();return;}
 if(d.buyRate){if(dispatch('setBuyRate',{rate:d.buyRate}))syncUI();return;}if('autoWholesale'in d){if(dispatch('setAutoWholesale',{on:!state.trade.autoWholesale}))syncUI();return;}if(d.wholesale){if(dispatch('wholesale',{id:d.wholesale,count:d.count==='all'?'all':+d.count}))syncUI();return;}if(d.workshopToggle){if(dispatch('toggleWorkshop',{workshop:d.workshopToggle}))syncUI();return;}if('sendCaravan'in d){if(dispatch('sendCaravan',{escort:d.sendCaravan==='escort'}))syncUI();return;}if(d.treasureSell){if(dispatch('sellTreasure',{index:+d.treasureSell}))syncUI();return;}if(d.treasureShow){if(dispatch('displayTreasure',{index:+d.treasureShow}))syncUI();return;}if('policyPetitions'in d){if(dispatch('setPolicy',{autoPetitions:state.policy?.autoPetitions===false}))syncUI();return;}if('policyHunt'in d){if(dispatch('setPolicy',{memberHunting:state.policy?.memberHunting===false}))syncUI();return;}
 if(d.inviteFree){if(dispatch('inviteFree',{freeId:d.inviteFree})){renderer?.setState(state);syncUI();}return;}
 if(d.watchMember){closeMenu();renderer?.startFollow('member',d.watchMember);return;}
 if(d.rankExam){if(dispatch('rankExam',{memberId:d.rankExam})){renderer?.setState(state);syncUI();}return;}
 if(d.lesson){if(dispatch('takeLesson',{memberId:d.lesson})){renderer?.setState(state);syncUI();}return;}
 if(d.hire){if(dispatch('recruit',{applicantId:d.hire})){renderer?.setState(state);syncUI();}return;}
 if(d.declineApp){if(dispatch('declineApplicant',{applicantId:d.declineApp}))syncUI();return;}
 if(d.autoWork){const m=state.members.find(m=>m.id===d.autoWork);if(m&&dispatch('setAutoWork',{memberId:m.id,autoWork:m.autoWork===false}))syncUI();}});

function renderQuestDetail(){const q=getAvailableQuests(state).find(q=>q.id===ui.questId);if(!q){ui.questId=null;return renderQuests();}const preview=previewMission(state,q.id,[...ui.selected],ui.policy),pet=detailPetition(),pay=pet&&getPayout(state,pet.fee,pet.plan);
 const chosen=[...ui.selected].map(id=>state.members.find(m=>m.id===id)).filter(Boolean),slots=[0,1,2].map(i=>{const m=chosen[i];return m?`<button class="slot filled" data-pick-member="${h(m.id)}" aria-label="เอา ${h(m.name)} ออก">${portrait(m)}<b>${h(m.name)}</b><small>${h(roleName(JOBS[m.class]?.role))} · Lv.${m.level}</small><i>✕</i></button>`:'<div class="slot empty"><span>+</span><small>เลือกสมาชิก</small></div>';}).join('');
 const roster=state.members.map(m=>{const low=!rankAllowsQuest(m,q),busy=isAway(m.id)||m.injury>40||low,on=ui.selected.has(m.id);return `<button class="pick ${on?'on':''} ${busy?'busy':''}" data-pick-member="${h(m.id)}" aria-pressed="${on}" ${busy?'disabled':''}>${portrait(m)}<span><b>${h(m.name)}</b><small>${h(jobName(m.class))} · Lv.${m.level} · แรงค์ ${h(m.rank||'F')}</small><small class="${q.tags.includes(JOBS[m.class]?.role)?'fit':''}">${busy?(low?`แรงค์ ${h(m.rank||'F')} รับงาน ${h(q.rank)} ไม่ได้`:isAway(m.id)?(m.errand?errandText(m):'ออกภารกิจ'):'ต้องรักษา'):q.tags.includes(JOBS[m.class]?.role)?'★ เหมาะกับงานนี้':roleName(JOBS[m.class]?.role)}</small><i class="mini-energy"><i style="width:${pct(m.energy)}%"></i></i></span></button>`;}).join('');
 const ratio=ui.selected.size?Math.min(1,(preview.readiness||0)/1.5):0,level=!ui.selected.size?'':preview.readiness>=.95?'good':preview.readiness>=.82?'ok':'bad';
 const policyNote={balanced:'เวลาและแรงปกติ',cautious:'ช้าลงแต่ปลอดภัยขึ้น',bold:'เร็วขึ้นแต่เหนื่อยและเสี่ยง'};
 return `<button class="back-button" data-back>‹ กระดานคำร้อง</button><div class="prep-hero"><canvas width="320" height="120" data-quest-art="${q.id}"></canvas><div class="prep-title"><small>${h(REGIONS.find(r=>r.id===q.region)?.name)}${q.story?' · เรื่องราว':''}</small><b>${h(q.name)}</b>${starLine(q)}</div></div><p class="detail-copy">${h(q.description)}</p>${pet?`<div class="pet-fee detail"><span>คำร้องจาก ${h(pet.client)}${pet.important?' · งานสำคัญ':''}</span><b>◈ ${n(pet.fee)} G</b><small>กิลด์ได้ ${n(pay.guild)} · ทีมได้ ${n(pay.adventurers)}</small></div>${planChips('pet-plan',pet.id,pet.plan,pet.fee)}`:'<div class="readiness warn">ยังไม่มีคำร้องนี้บนกระดาน รอชาวบ้านมาส่งคำร้องแล้วรับขึ้นกระดานก่อน</div>'}${rewardChips({...q.reward,gold:pay?.guild||0},'big')}${q.locked?`<div class="readiness warn">${h(q.lockReason)}</div>`:''}
 ${lootPreview(q)}<div class="section-title">ทีมเดินทาง<small>${ui.selected.size}/3 คน (ไปได้ตั้งแต่ 1 คน) · งานนี้เหมาะกับ ${q.tags.map(roleName).join(' / ')}</small></div><div class="team-slots">${slots}</div><div class="auto-row"><button data-auto-team>✨ จัดทีมให้</button><button class="primary" data-auto-send ${q.locked||!pet?'disabled':''}>⚡ ส่งอัตโนมัติ</button></div><div class="roster">${roster}</div>
 <div class="section-title">แผนการเดินทาง</div><div class="plan-row">${Object.entries(MISSION_POLICIES).map(([id,p])=>`<button data-policy="${id}" class="${ui.policy===id?'active':''}"><b>${h(p.name)}</b><small>${h(policyNote[id]||'')}</small></button>`).join('')}</div>
 <div class="power-meter ${level}"><div class="pm-head"><b>${h(ui.selected.size?(preview.ok?preview.verdict:preview.reason||'ตรวจความพร้อมทีม'):'เลือกสมาชิก 1–3 คน')}</b><small>${ui.selected.size?`พลังทีม ${n(preview.power)} / ความยาก ${n(preview.difficulty)}`:''}</small></div><div class="pm-bar"><i style="width:${pct(ratio,1)}%"></i><span style="left:${pct(1/1.5,1)}%"></span></div><div class="luck-row"><b>โชค</b><span class="luck-stars">${luckStars(ui.selected.size?preview.luck:0)}</span><small>${ui.selected.size?(preview.luck>=.2?'มีโอกาสเจอสมบัติหายากสูง':'นักธนู นิสัยช่างสังเกต เครื่องรางนำโชค และแผนรอบคอบช่วยเพิ่มโชค'):'เลือกทีมเพื่อดูโชค'}</small></div><small>${preview.missingRoles?.length?'ขาดบทบาท: '+preview.missingRoles.map(roleName).join(' · ')+' · ':''}เวลา ${n(preview.duration||q.duration)} วินาที · เสบียง ${h(moneyCost(preview.cost||q.cost))}</small></div>
 <button class="primary go-button" data-send-mission ${!preview.ok||q.locked||!pet?'disabled':''}>ออกเดินทาง!</button>`;}

function renderMission(){const m=state.missions.find(m=>m.id===ui.missionId);if(!m){ui.missionId=null;return renderQuests();}const q=QUESTS.find(q=>q.id===m.questId);const ongoing=m.status==='active'||m.status==='decision';return `<button class="back-button" data-back>‹ กลับกระดานคำร้อง</button><div class="mission-head"><b>${h(q?.name||m.questId)}</b><small>${h(REGIONS.find(r=>r.id===q?.region)?.name||'')} · ${n(missionRatio(m)*100)}%</small></div><canvas id="mission-scene" class="dungeon-view" width="400" height="220"></canvas>${ongoing?`<button class="secondary full-button watch-button" data-watch-mission="${h(m.id)}">📍 ดูทีมในโลก</button>`:''}${(()=>{if(!q)return'';const st=missionStage(m,buildDungeon(q)),done=!ongoing,at=done?4:st.back?4:st.fight>0?st.fight:st.target-.5;return `<div class="route">${['🏠','⚔','⚔','👑'].map((icon,i)=>`<span class="${i<at||done&&m.status==='completed'?'done':''} ${Math.abs(i-at)<.6&&!done?'here':''}">${icon}<small>${['ทางเข้า','ห้อง 1','ห้อง 2','บอส'][i]}</small></span>`).join('<i></i>')}</div>`;})()}<div class="section-title">${ongoing?'ความคืบหน้าการเดินทาง':m.status==='completed'?'ทีมกลับถึงบ้านแล้ว':m.status==='recalled'?'เรียกทีมกลับแล้ว':'ทีมถอยกลับมาพัก'}<small>${n(missionRatio(m)*100)}%</small></div><div class="progress"><i style="width:${pct(missionRatio(m),1)}%"></i></div>${missionEventPending(m)?`<div class="event-card" style="margin-top:15px"><h3>${h(m.event.title)}</h3><p>${h(m.event.text)}</p>${m.event.choices.map(c=>`<button data-event-choice="${h(c.id)}" data-mission="${h(m.id)}">${h(c.label)}<small>${h(c.description||'')}</small></button>`).join('')}</div>`:`<p class="detail-copy">${h(ongoing?(m.phase==='battle'?`พบ${q?.enemy} · การเตรียมทีมและอุปกรณ์มีผลกับการต่อสู้`:'สมาชิกกำลังสำรวจเส้นทาง คุณกลับไปจัดกิลด์ระหว่างรอได้'):(m.result?.message||'บันทึกการเดินทางอยู่ในสมุดกิลด์'))}</p>`}${ongoing?`<button class="secondary full-button" data-recall="${h(m.id)}">เรียกทีมกลับก่อน</button><p class="tiny-note">หยุดความเสี่ยงและกลับมาพัก เสบียงที่ใช้ไปไม่คืน และยังไม่ได้รางวัลคำร้อง</p>`:''}`;}
// ---- The roster: who is where at a glance, grouped by what they are doing. ----
const ZONE_NAMES=()=>Object.fromEntries(Object.entries(HUNT_ZONES).map(([k,z])=>[k,z.name]));
/** What a member is doing right now, as an icon, a short line, and the roster group it belongs to. */
function memberActivity(m){
 const hunter=state.world?.hunters?.find(h=>h.id===m.id),mission=activeMissions().find(x=>x.memberIds.includes(m.id)),zone=hunter&&ZONE_NAMES()[hunter.zone];
 if(hunter){const t={go:`เดินไป${zone}`,hunt:`ล่ามอนที่${zone} · ได้ ${hunter.bag?.kills||0} ตัว`,return:`กำลังกลับจาก${zone}`,carry:`แบกเพื่อนกลับจาก${zone}`,carried:`สลบ · กำลังถูกหามกลับ`,down:`สลบที่${zone}`,defend:'ป้องกันหมู่บ้าน'}[hunter.mode]||'ออกล่า';
  return{icon:hunter.mode==='carried'||hunter.mode==='down'?'💫':hunter.mode==='defend'?'🛡':'⚔',text:t,group:hunter.mode==='carried'||hunter.mode==='down'?'hurt':'out',hp:hunter.hp/hunter.maxHp,follow:true};}
 if(mission){const q=QUESTS.find(q=>q.id===mission.questId);return{icon:'📜',text:`${q?.name||'ภารกิจ'} · ${n(missionRatio(mission)*100)}%`,group:'out',mission:mission.id,follow:true};}
 if(m.errand)return{icon:m.errand.kind==='exam'?'🏟':'🥋',text:errandText(m),group:'out',follow:true};
 if(m.injury>20)return{icon:'🩹',text:`พักรักษา · บาดเจ็บ ${n(m.injury)}`,group:'hurt'};
 if(m.energy<60)return{icon:'💤',text:'พักฟื้นแรง',group:'home'};
 return{icon:'🏠',text:({train:'ฝึกกับหุ่น',work:'ช่วยงานกิลด์'})[m.task]||'ว่าง พร้อมออกงาน',group:'home'};
}
function rosterRow(m){const a=memberActivity(m),r=getAdventurerRank(state,m);
 return `<div class="roster-row ${a.group}"><button class="roster-main" data-member="${h(m.id)}">${portrait(m)}<span class="roster-id"><b>${h(m.name)} <span class="rank-chip">${h(m.rank||'F')}</span></b><small>${h(JOBS[m.class]?.icon||'')} ${h(jobName(m.class))} · Lv.${m.level}${r.eligible?' · <em class="ready">พร้อมสอบ</em>':''}</small></span><span class="roster-state"><small>${a.icon} ${h(a.text)}</small><span class="roster-bars"><i class="bar energy" title="แรง"><i style="width:${pct(m.energy)}%"></i></i>${a.hp!=null?`<i class="bar hp" title="พลังชีวิต"><i style="width:${pct(a.hp,1)}%"></i></i>`:''}${m.injury>0?`<i class="bar injury" title="บาดเจ็บ"><i style="width:${pct(m.injury)}%"></i></i>`:''}</span></span></button>${a.follow?`<button class="roster-watch" data-watch-member="${h(m.id)}" aria-label="ดู ${h(m.name)} บนแผนที่">📍</button>`:''}</div>`;}
function renderMembers(){const stats=getGuildStats(state);if(ui.memberId)return renderMemberDetail();
 const tab=ui.rosterTab||'guild',apps=(state.applicants||[]).filter(a=>a.status==='waiting').length,free=(state.world?.free||[]).filter(f=>f.mode!=='arrive');
 const tabs=`<div class="sheet-tabs roster-tabs">${[['guild',`สมาชิก ${stats.memberCount}/${stats.memberCap}`],['free',`นักผจญภัยอิสระ ${free.length}`],['door',`ผู้สมัคร${apps?' '+apps:''}`]].map(([id,label])=>`<button data-roster-tab="${id}" class="${tab===id?'active':''}">${h(label)}</button>`).join('')}</div>`;
 if(tab==='free')return tabs+renderFreeAdventurers(free);
 if(tab==='door')return tabs+renderApplicants();
 const groups=[['out','ออกไปข้างนอก','ล่ามอน ทำภารกิจ หรือไปเรียน/สอบ'],['home','อยู่ในกิลด์','พักฟื้นหรือพร้อมออกงาน'],['hurt','บาดเจ็บ / สลบ','ต้องพักรักษาก่อนออกงาน']];
 const by=Object.fromEntries(groups.map(([g])=>[g,[]]));for(const m of state.members)by[memberActivity(m).group].push(m);
 const count=g=>by[g].length;
 return tabs+`<div class="roster-summary">${groups.map(([g,label])=>`<span class="${g}"><b>${count(g)}</b>${h(label)}</span>`).join('')}</div>
 <div class="roster-policy"><button data-policy-hunt class="${state.policy?.memberHunting!==false?'on':''}">${state.policy?.memberHunting!==false?'☑':'☐'} ให้สมาชิกที่ว่างออกล่ามอนเอง</button><button data-auto-equip>🛡 จัดอุปกรณ์ดีที่สุดให้ทุกคน</button></div>
 ${groups.filter(([g])=>count(g)).map(([g,label,hint])=>`<div class="section-title">${h(label)}<small>${h(hint)}</small></div><div class="roster-list">${by[g].map(rosterRow).join('')}</div>`).join('')}
 ${apps?`<button class="inline-tip board-tip" data-roster-tab="door">🚪 มีผู้สมัครรออยู่ที่ประตู ${apps} คน · แตะเพื่อดู</button>`:''}`;}
function freeLook(f){return{id:f.id,name:f.name,class:f.class,hair:f.hair};}
function renderFreeAdventurers(list){const stats=getGuildStats(state),full=stats.memberCount>=stats.memberCap;
 if(!list.length)return '<p class="tiny-note">ยังไม่มีนักผจญภัยอิสระในเมือง เมื่อหมู่บ้านโตขึ้นจะมีคนมาพักที่โรงเตี๊ยมมากขึ้น</p>';
 return `<p class="tiny-note">นักผจญภัยอิสระพักที่โรงเตี๊ยม ล่ามอนเอง และขายของที่จุดรับซื้อของกิลด์ ยิ่งประทับใจกิลด์ ยิ่งยอมเข้าร่วม</p><div class="roster-list">${list.map(f=>{const hunter=f.mode==='out'&&state.world.hunters.find(h=>h.id===f.id),like=f.affinity>=40||state.rep>=f.level*25,fee=inviteFee(f);
  return `<div class="roster-row ${hunter?'out':'home'}"><div class="roster-main"><canvas class="portrait" width="64" height="72" data-free="${h(f.id)}"></canvas><span class="roster-id"><b>${h(f.name)} <span class="rank-chip">${h(f.rank)}</span></b><small>${h(JOBS[f.class]?.icon||'')} ${h(jobName(f.class))} · Lv.${f.level} · ${h(f.trait)}</small></span><span class="roster-state"><small>${hunter?`⚔ ล่ามอนที่${h(ZONE_NAMES()[hunter.zone]||'')}`:'🍺 อยู่ในเมือง'}</small><span class="roster-bars"><i class="bar like" title="ความประทับใจต่อกิลด์"><i style="width:${pct(f.affinity)}%"></i></i></span></span></div><button class="roster-invite" data-invite-free="${h(f.id)}" ${hunter||full||!like||state.gold<fee?'disabled':''}>${full?'เตียงเต็ม':!like?'ยังไม่สนใจ':`ชวน · ${n(fee)} G`}</button></div>`;}).join('')}</div>`;}
function renderMemberDetail(){const m=state.members.find(m=>m.id===ui.memberId);if(!m){ui.memberId=null;return renderMembers();}
 const def=contentOf(m),stats=getMemberStats(state,m),a=memberActivity(m),tab=ui.memberTab||'overview';
 const bonds=Object.entries(state.bonds||{}).filter(([key])=>key.split(':').includes(m.id)).sort((x,y)=>y[1]-x[1]);
 const head=`<button class="back-button" data-back>‹ สมาชิกกิลด์</button><div class="member-hero">${portrait(m)}<div><h2>${h(m.name)} <span class="rank-chip">${h(m.rank||'F')}</span></h2><p>${h(jobName(m.class))} · Lv.${m.level} · ${h(def?.trait||'')}</p><p class="hero-activity">${a.icon} ${h(a.text)}${a.follow?` <button class="tiny-watch" data-watch-member="${h(m.id)}">📍 ดูบนแผนที่</button>`:''}</p></div></div><div class="hero-bars"><span>แรง<i class="bar energy"><i style="width:${pct(m.energy)}%"></i></i><b>${n(m.energy)}</b></span><span>ขวัญ<i class="bar morale"><i style="width:${pct(m.morale)}%"></i></i><b>${n(m.morale)}</b></span><span>บาดเจ็บ<i class="bar injury"><i style="width:${pct(m.injury)}%"></i></i><b>${n(m.injury)}</b></span><span>XP<i class="bar xp"><i style="width:${pct(m.xp,stats.xpNeeded)}%"></i></i><b>${n(m.xp)}/${n(stats.xpNeeded)}</b></span></div>
 <div class="sheet-tabs">${[['overview','ภาพรวม'],['growth','แรงค์และคลาส'],['gear','อุปกรณ์']].map(([id,label])=>`<button data-member-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div>`;
 if(tab==='growth')return head+renderGrowth(m);
 if(tab==='gear')return head+`<div class="gear-state"><span>◈ เงินส่วนตัว ${n(m.purse||0)} G</span><span>🎒 เสบียง ${n(m.pack?.ration||0)} · ยา ${n(m.pack?.potion||0)}</span></div>${['weapon','accessory'].map(slot=>{const e=item(m.equipment?.[slot]),wear=m.wear?.[slot]??100;return`<div class="equipment-row">${e?itemIcon(e.id):'<span class="build-icon" style="width:28px;height:28px;font-size:14px">'+(slot==='weapon'?'⚔':'✧')+'</span>'}<span>${h(e?.name||(slot==='weapon'?'ยังไม่มีอาวุธ':'ยังไม่มีเครื่องราง'))}<small>${e?`พลัง +${e.power} · ความทนทาน ${n(wear)}%${wear<25?' (สึกมาก)':''}`:(slot==='weapon'?'อาวุธ':'เครื่องประดับ')}</small></span>${e?`<button data-unequip="${slot}" data-member-id="${h(m.id)}" ${isAway(m.id)?'disabled':''} style="font-size:9px;padding:3px 6px">ถอด</button>`:''}</div>`;}).join('')}<p class="tiny-note">สมาชิกซื้อ ซ่อม และอัปเกรดอุปกรณ์เองด้วยเงินส่วนตัวเมื่อมีร้านในหมู่บ้าน กิลด์ช่วยได้ด้วยของจากโต๊ะช่างและหีบสมบัติ</p><button class="secondary full-button" data-tab="workshop">คราฟต์และเลือกอุปกรณ์ →</button>`;
 return head+`<div class="trait">${h(def?.description||'')}</div><div class="stat-grid"><div class="stat-box">พลังต่อสู้<b>${n(stats.power)}</b></div><div class="stat-box">พลังชีวิต<b>${n(stats.health)}</b></div><div class="stat-box">ภารกิจสำเร็จ<b>${n(m.missionsDone)}</b></div><div class="stat-box">แต้มผลงาน<b>${n(m.points||0)}</b></div></div>${stats.waitingReason?`<div class="inline-tip">${h(stats.waitingReason)}</div>`:''}
 <div class="section-title">ทำอะไรเมื่ออยู่กิลด์</div><div class="segmented">${[['rest','พักฟื้น'],['train','ฝึกกับหุ่น'],['work','ช่วยงาน']].map(([id,label])=>`<button data-task="${id}" data-member-id="${h(m.id)}" class="${m.task===id?'active':''}" ${isAway(m.id)?'disabled':''}>${label}</button>`).join('')}</div>
 <button class="secondary full-button" data-auto-work="${h(m.id)}">${m.autoWork===false?'☐ ออกงานเอง (ปิดอยู่ · รอให้คุณสั่ง)':'☑ ออกงานเองเมื่อว่าง (หยิบงานจากกระดาน ล่ามอน เรียน และสอบ)'}</button>
 ${bonds.length?`<div class="section-title">เพื่อนร่วมทาง</div>${bonds.slice(0,5).map(([key,value])=>{const other=state.members.find(x=>x.id===key.split(':').find(id=>id!==m.id));return other?`<div class="bond-row">${h(other.name)}<span>ความไว้ใจ ${n(value)}</span></div>`:'';}).join('')}`:''}`;}
function renderRoomDetail(room){
 const size=partitionSize(room),inside=state.facilities.filter(f=>containsRect(partitionRect(room),{...f,...getRoomSize(f.type,f.rotation||0)}));
 return `<button class="back-button" data-back>‹ ห้องและต่อเติม</button><h2 class="detail-title">${h(ROOM_TYPES[room.type].name)}</h2><p class="detail-copy">${size.w} × ${size.h} ช่อง · ของภายใน ${inside.length} ชิ้น</p><div class="facility-actions"><button data-move-room="${h(room.id)}">ย้ายทั้งห้อง</button><button data-rotate-room="${h(room.id)}">หมุนทั้งห้อง 90°</button></div><p class="tiny-note">ย้ายและหมุนพร้อมของภายใน ต้องเว้นทางเดินผ่านประตู</p><div class="room-size"><label>กว้าง<input aria-label="ปรับความกว้างห้อง" data-partition-size="width" type="number" min="2" max="14" step="1" value="${ui.roomDraftW??room.width}"></label><label>ลึก<input aria-label="ปรับความลึกห้อง" data-partition-size="height" type="number" min="2" max="14" step="1" value="${ui.roomDraftH??room.height}"></label></div><button class="primary full-button" data-resize-room="${h(room.id)}">ปรับขนาดห้อง</button><p class="tiny-note">เพิ่มขนาดใช้วัสดุตามพื้นที่ ลดขนาดได้เมื่อของภายในยังพอดี</p><div class="section-title">ของภายในห้อง</div>${inside.map(f=>`<button class="facility-row" data-facility="${h(f.id)}"><span>${h(FACILITIES[f.type].name)}</span><span>Lv.${f.level} →</span></button>`).join('')||'<p class="tiny-note">ห้องว่าง เลือกของจากเมนูแล้ววางภายในได้</p>'}<button class="danger full-button" data-demolish-room="${h(room.id)}">รื้อผนังห้อง</button><p class="tiny-note">ของภายในยังอยู่บนพื้นที่โล่ง</p>`;
}
function renderAreaStages(){const b=state.building,next=BUILDING_STAGES[b.level+1];return `<div class="expansion-card"><b>พื้นที่อาคาร ${b.width} × ${b.height}</b><p>ต่อเติมพื้นโล่งทีละขั้น แล้วเลือกสร้างห้องเอง</p><div class="area-stages">${BUILDING_STAGES.map((stage,i)=>`<div class="area-stage ${i===b.level?'current':''}"><span>${h(stage.name)}<small>${stage.width} × ${stage.height} ช่อง</small></span><b>${i<=b.level?'เปิดแล้ว':i===b.level+1&&rankEnough(stage.rank)?'ขั้นถัดไป':'กิลด์ '+stage.rank}</b></div>`).join('')}</div>${next?`<p class="build-cost">${h(moneyCost(getBuildingExpansionCost(state)))}</p><button class="primary" data-expand-building ${!rankEnough(next.rank)||!canAfford(getBuildingExpansionCost(state))?'disabled':''}>${rankEnough(next.rank)?'เปิดพื้นที่ขั้น '+(b.level+1)+' →':'ต้องมีกิลด์ '+next.rank}</button>`:'<p class="tiny-note">เปิดพื้นที่อาคารครบทุกขั้นแล้ว</p>'}</div>`;}
function renderRoomBuilder(){return `<div class="section-title">สร้างห้องบนพื้นที่โล่ง</div><p class="tiny-note">กำหนดขนาด เลือกชนิด แล้วแตะพื้นเพื่อวาง ประตูหมุนตามทิศห้อง จัดของแยกชิ้นภายในได้</p><div class="room-size"><label>กว้าง<input id="room-width" aria-label="ความกว้างห้องใหม่" data-room-dimension="width" type="number" min="2" max="14" step="1" value="${ui.roomWidth}"></label><label>ลึก<input id="room-height" aria-label="ความลึกห้องใหม่" data-room-dimension="height" type="number" min="2" max="14" step="1" value="${ui.roomHeight}"></label></div><p id="room-estimate" class="build-cost">${h(moneyCost(getPartitionCost(ui.roomWidth,ui.roomHeight)))}</p><div class="room-catalog">${Object.entries(ROOM_TYPES).map(([type,r])=>`<button data-room-type="${type}"><span style="background:${r.color}"></span>${h(r.name)}</button>`).join('')}</div>${state.rooms.length?`<div class="section-title">ห้องที่วางแล้ว</div>${state.rooms.map(room=>{const d=partitionSize(room);return `<button class="facility-row" data-partition="${h(room.id)}"><span>${h(ROOM_TYPES[room.type].name)}</span><span>${d.w}×${d.h} →</span></button>`;}).join('')}`:''}<div class="section-title">จัดของบนพื้นหรือภายในห้อง</div>`;}
function renderBuild(){
 const faces=['↘','↙','↖','↗'];
 if(ui.partitionId){const room=state.rooms.find(r=>r.id===ui.partitionId);if(room)return renderRoomDetail(room);}
 if(ui.facilityId){const f=state.facilities.find(f=>f.id===ui.facilityId);if(f){const d=FACILITIES[f.type],size=getRoomSize(f.type,f.rotation||0);return `<button class="back-button" data-back>‹ ห้องและต่อเติม</button><h2 class="detail-title">${h(d.name)}</h2><p class="detail-copy">${h(d.description)}</p><div class="stat-grid"><div class="stat-box">ระดับ<b>${f.level} / 3</b></div><div class="stat-box">พื้นที่ / ทิศ<b>${size.w} × ${size.h} ${faces[f.rotation||0]}</b></div></div><button class="primary full-button" data-upgrade="${h(f.id)}" ${f.level>=3?'disabled':''}>อัปเกรด</button><p class="tiny-note">${h(moneyCost(getUpgradeCost(state,f.id)))}</p><div class="facility-actions"><button data-move="${h(f.id)}">ย้าย / จัดวาง</button><button data-rotate="${h(f.id)}">หมุน 90°</button><button class="danger" data-demolish="${h(f.id)}">เก็บออก</button></div><div class="inline-tip">จัดวางทีละหนึ่งในสี่ช่อง เว้นทางเข้ากับด้านใช้งานของแต่ละชิ้น</div>`;}}
 const tab=ui.buildTab||'items',tabs=`<div class="sheet-tabs">${[['items','ของในบ้าน'],['rooms','ห้อง'],['expand','ต่อเติม']].map(([id,label])=>`<button data-build-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div>`;
 if(tab==='rooms')return tabs+renderRoomBuilder().replace('<div class="section-title">จัดของบนพื้นหรือภายในห้อง</div>','');
 if(tab==='expand')return tabs+renderAreaStages()+`<div class="expansion-card"><b>ที่ดิน ${state.grid.width}×${state.grid.height}</b><p>ซื้อที่ดินรอบกิลด์เพิ่ม วางแปลงสมุนไพรกลางแจ้งได้</p><p class="build-cost">${h(moneyCost(getExpansionCost(state)))}</p><button data-expand ${state.landLevel>=2||!rankEnough(state.landLevel===0?'E':'C')||!canAfford(getExpansionCost(state))?'disabled':''}>ซื้อที่ดินเพิ่ม →</button></div>`;
 return tabs+`<p class="tiny-note">แตะของที่อยากได้ แล้วแตะพื้นในบ้านเพื่อวาง</p><div class="shop-grid">${Object.entries(FACILITIES).map(([type,f])=>{const locked=!rankEnough(f.unlockRank),unique=['reception','dispatch','board'].includes(type)&&state.facilities.some(o=>o.type===type),afford=canAfford(f.cost),owned=state.facilities.filter(o=>o.type===type).length;return `<button class="shop-card ${locked?'locked':''}" data-build="${type}" ${locked||unique||!afford?'disabled':''}><canvas class="shop-art" width="128" height="88" data-furniture="${type}"></canvas><b>${h(f.name)}</b><small>${h(f.description)}</small><span class="shop-cost ${afford?'':'short'}">${h(moneyCost(f.cost))}</span>${locked?`<i class="shop-tag lock">กิลด์ ${h(f.unlockRank)}</i>`:unique?'<i class="shop-tag">วางแล้ว</i>':owned?`<i class="shop-tag">มี ${owned}</i>`:''}</button>`;}).join('')}</div><div class="section-title">ของที่วางอยู่</div>${state.facilities.map(f=>`<button class="facility-row" data-facility="${h(f.id)}"><span>${h(FACILITIES[f.type].name)}</span><span>Lv.${f.level} ${faces[f.rotation||0]} →</span></button>`).join('')}`;
}

function equipmentCard(e,maxWorkshop){const eligible=state.members.filter(m=>!isAway(m.id)&&(!e.classes.length||e.classes.includes(baseJob(m.class))));const count=availableCount(e.id);const locked=!rankEnough(e.unlockRank)||maxWorkshop<e.workshopLevel;return `<div class="item-card ${e.loot?'treasure '+e.rarity:''}"><div class="item-top">${itemIcon(e.id)}<div><b>${h(e.name)}</b><small>${e.slot==='weapon'?'อาวุธ':'เครื่องราง'} · พลัง +${e.power} · ในคลัง ${count}</small></div></div><p>${h(e.description)}${e.classes.length?' · '+e.classes.map(jobName).join('/'):' · ทุกอาชีพ'}</p>${e.loot?`<div class="build-cost" style="color:${RARITIES[e.rarity].color}">✦ สมบัติ${h(RARITIES[e.rarity].name)}${e.luck?' · โชค +'+Math.round(e.luck*100)+'%':''}</div>`:`<div class="build-cost">${h(moneyCost(getCraftCost(state,e)))}${state.village?.smithy?' · ส่วนลดโรงตีเหล็ก':''}</div>`}<div class="item-actions" style="margin-top:8px">${inventoryCount(e.id)>0?`<button class="secondary" data-sell="${e.id}">ขาย +${n(getSellPrice(e.id))} G</button>`:''}${e.loot?'':`<button class="${locked?'secondary':'primary'}" data-craft="${e.id}" ${locked||!canAfford(getCraftCost(state,e))?'disabled':''}>${locked?'ต้องการกิลด์ '+e.unlockRank+' / โต๊ะช่าง '+e.workshopLevel:'คราฟต์'}</button>`}${count>0&&eligible.length?`<select aria-label="สมาชิกที่สวม ${h(e.name)}" data-equip-select="${e.id}">${eligible.map(m=>`<option value="${h(m.id)}">${h(m.name)}</option>`).join('')}</select><button data-equip="${e.id}">ใส่</button>`:''}</div></div>`;}
function renderWorkshop(){const maxWorkshop=Math.max(0,...state.facilities.filter(f=>f.type==='workshop').map(f=>f.level));return `<p class="panel-intro">ของจากการเดินทาง กลายเป็นอุปกรณ์ชิ้นใหม่<br>คราฟต์ก่อน แล้วเลือกสมาชิกเพื่อสวมใส่</p>${EQUIPMENT.filter(e=>!e.loot).map(e=>equipmentCard(e,maxWorkshop)).join('')}${(()=>{const owned=EQUIPMENT.filter(e=>e.loot&&(inventoryCount(e.id)>0||state.members.some(m=>Object.values(m.equipment||{}).includes(e.id))));return owned.length?'<div class="section-title">สมบัติจากการผจญภัย</div>'+owned.map(e=>equipmentCard(e,maxWorkshop)).join(''):'<p class="tiny-note">สมบัติหายากหาได้จากหีบในดันเจียนเท่านั้น ทีมที่โชคดีจะเจอของดีบ่อยขึ้น</p>';})()}`;}
function eventHistory(){const list=state.director?.history||[];return list.length?`<div class="section-title">เหตุการณ์ในหมู่บ้าน</div><div class="event-history">${list.slice(0,10).map(e=>`<div class="event-row"><span class="event-icon">${h(e.icon)}</span><div><b>${h(e.title)}</b><small>วันที่ ${h(e.day)}${e.outcome?' · '+h(e.outcome):''}</small></div></div>`).join('')}</div>`:'';}
// ---- Trade: the guild counter, storehouse, workshops, caravan and treasures ----
function renderTrade(){const t=state.trade,cap=storeCapacity(state),used=storeUsed(t),rate=BUY_RATES[t.buyRate],v=state.village||{};
 const kinds={hide:'หนังและเส้นใย',essence:'ของเหลวและผง',gem:'เขา เปลือก และผลึก'};
 const parts=Object.entries(t.store).sort((a,b)=>PARTS[a[0]].kind.localeCompare(PARTS[b[0]].kind)||PARTS[b[0]].value-PARTS[a[0]].value);
 const partRow=([id,n])=>{const p=PARTS[id];return `<div class="trade-row"><span class="trade-icon">${p.icon}</span><div><b>${h(p.name)} ×${n}</b><small>${h(kinds[p.kind])} · รับซื้อ ${Math.round(p.value*rate.rate)} G · ขายส่งตอนนี้ ${wholesalePrice(t,id)} G</small></div><div class="trade-btns"><button class="secondary" data-wholesale="${id}" data-count="5">ขาย 5</button><button class="secondary" data-wholesale="${id}" data-count="all">ขายหมด</button></div></div>`;};
 const shops=Object.entries(GOODS).map(([id,g])=>{const lv=v[g.workshop]||0,job=t.work[g.workshop],stock=t.goods[id],have=Object.entries(t.store).filter(([p])=>PARTS[p].kind===g.kind).reduce((s,[,n])=>s+n,0),halt=t.halt[g.workshop];
  const status=!lv?'ยังไม่ได้สร้าง · สร้างได้ในแท็บหมู่บ้าน':halt?'หยุดรับวัตถุดิบ':job?.busy?`กำลังทำ ${Math.round(job.progress/TRADE_RULES.workTime*100)}%`:`รอวัตถุดิบ (${have}/${TRADE_RULES.recipe})`;
  return `<div class="trade-row ${lv?'':'locked'}"><span class="trade-icon">${g.icon}</span><div><b>${h(VILLAGE_PROJECTS[g.workshop].name)}${lv?' Lv.'+lv:''} → ${h(g.name)}</b><small>${h(status)}${stock?.count?` · มี ${g.name} ${stock.count} ชิ้น (ชิ้นละ ~${Math.round(goodValue(stock))} G)`:''}</small>${lv&&job?.busy?`<i class="goal-progress"><i style="width:${pct(job.progress,TRADE_RULES.workTime)}%"></i></i>`:''}</div><div class="trade-btns">${lv?`<button class="secondary" data-workshop-toggle="${g.workshop}">${halt?'เปิด':'พัก'}</button>`:''}${stock?.count?`<button class="secondary" data-wholesale="${id}" data-count="all">ขายส่ง</button>`:''}</div></div>`;}).join('');
 let caravan;if(!v.caravan)caravan=`<p class="tiny-note">สร้าง <b>ลานคาราวาน</b> ในแท็บหมู่บ้าน (หมู่บ้านระดับ 2) เพื่อขนของไปขายเมืองหลวงได้ราคา ×${TRADE_RULES.caravanMarkup} และรับใบสั่งซื้อโบนัส</p>`;
 else if(t.caravan){const c=t.caravan;caravan=`<div class="trade-row"><span class="trade-icon">🐎</span><div><b>คาราวานกำลังเดินทาง · ของ ${c.count} ชิ้น</b><small>กลับในอีก ${Math.ceil(c.left/60)} นาที · มูลค่าของ ${n(c.value)} G${c.escort?' · มีผู้คุ้มกัน':' · ไม่มีผู้คุ้มกัน (เสี่ยงโจร)'}</small><i class="goal-progress"><i style="width:${pct(c.total-c.left,c.total)}%"></i></i></div></div>`;}
 else{const plan=caravanLoad(state),ct=t.contract,cn=ct&&(PARTS[ct.id]||GOODS[ct.id]);caravan=`${ct?`<div class="trade-contract">📜 ใบสั่งซื้อจากเมืองหลวง: <b>${h(cn.name)} ${ct.count} ชิ้น</b> · โบนัส +${Math.round(TRADE_RULES.contractBonus*100)}% ของมูลค่า ${plan.met?'<span class="ok">ครบแล้ว ✓</span>':''}</div>`:''}<div class="trade-row"><span class="trade-icon">🐎</span><div><b>บรรทุกได้ ${plan.count}/${plan.cap} ชิ้น</b><small>มูลค่าของ ${n(plan.value)} G → คาดว่าขายได้ ~${n(plan.expect)} G · ไป-กลับ ${Math.round(TRADE_RULES.caravanTime/60)} นาที · ไม่มีผู้คุ้มกันเสี่ยงโจร ${Math.round(TRADE_RULES.caravanRisk*100)}%</small></div><div class="trade-btns"><button class="secondary" data-send-caravan ${plan.count?'':'disabled'}>ส่ง</button><button class="primary" data-send-caravan="escort" ${plan.count&&state.gold>=TRADE_RULES.escortCost?'':'disabled'}>ส่ง + คุ้มกัน ${TRADE_RULES.escortCost} G</button></div></div>`;}
 const treasures=t.treasures.map((x,i)=>{const d=TREASURES[x.id];return `<div class="trade-row treasure"><span class="trade-icon">${d.icon}</span><div><b>${h(d.name)}</b><small>${x.from?h(x.from)+'เจอระหว่างล่า · ':''}นักสะสมให้ ${n(d.value)} G · จัดแสดงได้ชื่อเสียง +${d.rep}</small></div><div class="trade-btns"><button class="secondary" data-treasure-sell="${i}">ขาย ${n(d.value)} G</button><button class="primary" data-treasure-show="${i}" ${t.displayed.length>=TRADE_RULES.displaySlots?'disabled':''}>จัดแสดง</button></div></div>`;}).join('');
 const shown=t.displayed.length?`<div class="display-case">${t.displayed.map(x=>`<span title="${h(TREASURES[x.id].name)}">${TREASURES[x.id].icon}</span>`).join('')}${'<span class="empty"></span>'.repeat(TRADE_RULES.displaySlots-t.displayed.length)}</div><p class="tiny-note">ตู้จัดแสดง ${t.displayed.length}/${TRADE_RULES.displaySlots} · ค่าเข้าชมวันละ ~${n(Math.round(t.displayed.reduce((s,x)=>s+TREASURES[x.id].value,0)*TRADE_RULES.displayTip))} G</p>`:'';
 return `<div class="stat-grid"><div class="stat-box">โกดัง<b>${used}/${cap} ชิ้น</b></div><div class="stat-box">รับซื้อแล้ว<b>${n(t.stats.bought)} ชิ้น</b></div><div class="stat-box">จ่ายรับซื้อ<b>${n(t.stats.spent)} G</b></div><div class="stat-box">ขายได้รวม<b>${n(t.stats.earned)} G</b></div></div>
 <div class="section-title">ราคารับซื้อที่เคาน์เตอร์<small>นักผจญภัยกลับจากล่าแล้วขายของให้กิลด์</small></div><div class="plan-chips">${Object.entries(BUY_RATES).map(([id,r])=>`<button data-buy-rate="${id}" class="${t.buyRate===id?'active':''}"><b>${h(r.name)}</b><small>${Math.round(r.rate*100)}% ของราคากลาง</small></button>`).join('')}</div><p class="tiny-note">${h(rate.description)} · กิลด์รับซื้อเมื่อเงินเหลือมากกว่า ${TRADE_RULES.reserve} G และโกดังยังมีที่</p>
 ${t.treasures.length?`<div class="section-title">สมบัติรอตัดสินใจ</div>${treasures}`:''}${shown?`<div class="section-title">ห้องจัดแสดงของกิลด์</div>${shown}`:''}
 <div class="section-title">โรงงานแปรรูป<small>วัตถุดิบ ${TRADE_RULES.recipe} ชิ้น → สินค้า 1 ชิ้น มูลค่า ×${TRADE_RULES.goodsValue}</small></div>${shops}<p class="tiny-note">ชาวเมืองซื้อสินค้าทุกเช้า ชนิดละ ${TRADE_RULES.townDemand+getVillageInfo(state).level*TRADE_RULES.townDemandPerLevel} ชิ้น ส่วนที่เหลือส่งคาราวานได้</p>
 <div class="section-title">คาราวานไปเมืองหลวง</div>${caravan}
 <div class="section-title">โกดัง<small><button class="link-button" data-auto-wholesale>${t.autoWholesale?'☑':'☐'} ขายส่งเองเมื่อใกล้เต็ม</button></small></div>${parts.length?parts.map(partRow).join(''):'<p class="tiny-note">โกดังว่าง นักผจญภัยจะนำชิ้นส่วนมอนมาขายเมื่อกลับจากการล่า</p>'}
 ${t.recent.length?`<div class="section-title">ความเคลื่อนไหวล่าสุด</div>${t.recent.map(x=>`<div class="ledger-row"><span>${h(x)}</span></div>`).join('')}`:''}`;}
function renderJournal(){const stats=getGuildStats(state);const nextRequirement=RANK_REQUIREMENTS[stats.nextRank];const nextQuest=QUESTS.find(q=>q.id===nextRequirement?.quest);let goals=state.story?.finished?['ช่วยทีมสำรวจกลับบ้าน','รักษาหัวใจป่า','มีบ้านให้ทุกคนกลับมา']:[stats.nextRank?`ชื่อเสียง ${n(state.rep)} / ${n(nextRequirement?.rep||0)}`:'กิลด์ระดับ A',nextQuest?`สำเร็จคำร้อง ${nextQuest.name}`:'สำเร็จคำร้องรักษาหัวใจป่า'];const ledger=(state.ledger||[]).slice(0,8);return `${state.story?.finished?'<div class="finished-banner"><b>ทุกคนกลับบ้านแล้ว ❧</b><br>จบบทแรกของเดโม่แล้ว ขอบคุณที่ดูแลนักผจญภัยทุกคน เล่นต่อ รับคนใหม่ และพัฒนาหมู่บ้านได้ · แผนที่ใหม่และระดับ B ขึ้นไปจะมาในเกมเต็ม</div>':''}<div class="chapter-card"><small>OUR GUILD STORY · CHAPTER ${state.story?.chapter||1}</small><h2>${state.story?.finished?'บ้านใต้ร่มใบไม้':stats.nextRank?'ก้าวต่อไป · กิลด์ระดับ '+stats.nextRank:'รักษาหัวใจป่า'}</h2><p>จากบ้านเล็กท้ายเมือง สู่สถานที่ที่ผู้คนฝากความหวัง</p></div>${renderPromotion()}<div class="stat-grid"><div class="stat-box">คำร้องที่สำเร็จ<b>${n(Object.values(state.completedQuests||{}).reduce((s,v)=>s+Number(v||0),0))} งาน</b></div><div class="stat-box">ค่าดูแลต่อวัน<b>${n(stats.upkeep)} G</b></div><div class="stat-box">รายรับวันนี้<b>${n(stats.incomeToday)} G</b></div><div class="stat-box">รายจ่ายวันนี้<b>${n(stats.expenseToday)} G</b></div></div><div class="section-title">ช่วงเวลาดี ๆ ในกิลด์</div>${GUILD_EVENTS.map(e=>`<div class="item-card"><b style="font-size:12px">${h(e.name)}</b><p>${h(e.description)}</p><div class="build-cost">${h(moneyCost(e.cost))}</div><button class="secondary full-button" data-host-event="${e.id}" ${!state.facilities.some(f=>f.type===e.requires)||!canAfford(e.cost)?'disabled':''}>${state.facilities.some(f=>f.type===e.requires)?'จัดกิจกรรม':'ต้องมี'+FACILITIES[e.requires].name}</button></div>`).join('')}<div class="section-title">บัญชีล่าสุด</div>${ledger.length?ledger.map(entry=>{const amount=Number(entry.amount||entry.gold||0);return`<div class="ledger-row"><span>${h(entry.label||entry.text||entry.reason||entry.type)} · วันที่ ${entry.day}</span><b class="${amount<0?'negative':''}">${amount>0?'+':''}${n(amount)} G</b></div>`;}).join(''):'<p class="tiny-note">เริ่มรับคำร้องเพื่อเพิ่มรายรับของกิลด์</p>'}${eventHistory()}<div class="section-title">เรื่องราวที่เกิดขึ้น</div>${(state.log||[]).slice(0,14).map(entry=>`<div class="log-entry"><small>วันที่ ${h(entry.day)} · GUILD MEMORY</small>${h(entry.text)}</div>`).join('')}`;}
function navigate(tab){ui.partitionId=null;ui.petitionId=null;ui.roomDraftW=null;ui.roomDraftH=null;ui.tab=tab;openMenu();ui.questId=null;ui.memberId=null;ui.facilityId=null;ui.missionId=null;ui.selected.clear();syncUI();$('panel-content').scrollTop=0;}
function cancelBuild(){if(ui.villagePlace){ui.villagePlace=null;renderer?.stopVillagePlacement();}ui.buildType=null;ui.moveId=null;ui.roomPlacement=null;ui.moveRoomId=null;renderer?.setRoomMode(null);renderer?.setBuildMode(null);renderer?.setMoveMode(null);syncHUD();}
function onSceneSelect(selection){if(selection.kind==='mission'){openMenu();ui.tab='quests';ui.missionId=selection.id;ui.questId=null;ui.memberId=null;syncUI();return;}if(selection.kind==='pickup'){const f=state.facilities.find(f=>f.id===selection.id);if(!f)return;closeMenu();ui.buildType=null;ui.roomPlacement=null;ui.moveRoomId=null;ui.facilityId=null;ui.moveId=f.id;syncHUD();return;}if(selection.kind==='member'&&selection.id==='master'){cancelBuild();openSetup('edit');return;}if(selection.kind==='room'&&ui.roomPlacement){if(dispatch('buildRoom',{...ui.roomPlacement,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='moveRoom'&&ui.moveRoomId){if(dispatch('moveRoom',{roomId:ui.moveRoomId,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='partition'){cancelBuild();navigate('build');ui.partitionId=selection.id;syncUI();}else if(selection.kind==='build'&&ui.buildType){if(dispatch('build',{type:ui.buildType,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='move'&&ui.moveId){if(dispatch('move',{facilityId:ui.moveId,x:selection.x,y:selection.y,rotation:selection.rotation})){cancelBuild();syncUI();}}else if(selection.kind==='member'){cancelBuild();navigate('members');ui.memberId=selection.id;syncUI();}else if(selection.kind==='facility'){cancelBuild();navigate('build');ui.facilityId=selection.id;syncUI();}}
let confirmCallback;
function confirmAction(title,message,callback){$('confirm-title').textContent=title;$('confirm-message').textContent=message;confirmCallback=callback;$('confirm-dialog').showModal();}
$('confirm-cancel').addEventListener('click',()=>{$('confirm-dialog').close();confirmCallback=null;});$('confirm-ok').addEventListener('click',()=>{$('confirm-dialog').close();const callback=confirmCallback;confirmCallback=null;callback?.();});
function openSettings(){$('management-dialog').close();$('settings-content').innerHTML=`<h2>บ้านหลังนี้ บันทึกไว้ได้</h2><p>เซฟอยู่ในเบราว์เซอร์ของเครื่องนี้ ส่งออกไฟล์เพื่อสำรองหรือย้ายไปเครื่องอื่นได้</p>${saveFailure?`<div class="save-warning">${h(saveFailure)}</div>`:''}<div class="settings-row"><button class="primary" data-save-now>บันทึกตอนนี้</button><button data-export-save>ส่งออกเซฟ</button><button data-import-save>นำเข้าเซฟ</button></div><div class="settings-divider"></div><h3>เสียงและการควบคุม</h3><div class="settings-row"><button data-toggle-sound>${ui.sound?'♪ เสียงเปิด':'♪ เสียงปิด'}</button></div><p>ลากฉากเพื่อเลื่อน · ใช้ + / − หรือสองนิ้วเพื่อซูม<br>กดพื้นห้องเพื่อย้าย/หมุนทั้งห้อง · กดของเพื่อจัดวาง/อัปเกรด · กดคนเพื่อดูรายละเอียด<br>Space หยุดเวลา · 1 / 2 / 4 เร่งเวลา · R หมุน · Esc ยกเลิกการวาง</p><div class="settings-divider"></div><h3>เริ่มการเดินทางใหม่</h3><p>เริ่มกิลด์ใหม่จะเขียนทับเซฟของเครื่องนี้ ส่งออกเซฟเดิมไว้ก่อนหากต้องการเก็บ</p><button class="danger" data-new-game>เริ่มกิลด์ใหม่</button><p class="tiny-note">เวอร์ชันแรกที่เล่นได้ · ความยาวแคมเปญยังอยู่ระหว่างปรับสมดุล</p>`;$('settings-dialog').showModal();}
$('settings-button').addEventListener('click',openSettings);
$('import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>2000000){toast('ไฟล์เซฟใหญ่เกินไป',true);return;}try{const imported=deserializeGame(await file.text());$('settings-dialog').close();confirmAction('ใช้เซฟจากไฟล์นี้?',`กิลด์ระดับ ${imported.rank} วันที่ ${imported.day} · ข้อมูลปัจจุบันจะถูกแทนที่`,()=>{state=imported;state.settings.paused=false;ui={...ui,tab:'quests',region:'meadow',questId:null,memberId:null,missionId:null,facilityId:null,selected:new Set(),paused:false,speed:state.settings.speed||1,sound:!!state.settings.sound,tutorial:!state.completedQuests?.patrol};cancelBuild();renderer?.setState(state);renderer?.resetView?.();seenLog=state.log[0];save();syncUI();toast('นำเข้ากิลด์เรียบร้อย');});}catch(error){toast('ไฟล์เซฟไม่ถูกต้องหรือไม่รองรับ ข้อมูลปัจจุบันยังอยู่',true);}});
document.addEventListener('click',event=>{const b=event.target.closest('button,[role="button"]');if(!b||b.disabled)return;const d=b.dataset;if(d.tab){navigate(d.tab);return;}if(d.region){ui.region=d.region;syncUI();return;}if(d.quest){ui.questId=d.quest;ui.missionId=null;ui.selected.clear();syncUI();return;}if(d.member){ui.memberId=d.member;ui.tab='members';syncUI();return;}if(d.facility){ui.partitionId=null;ui.facilityId=d.facility;ui.tab='build';syncUI();return;}if(d.openMission){openMenu();ui.tab='quests';ui.missionId=d.openMission;ui.questId=null;syncUI();return;}if('back'in d){ui.partitionId=null;ui.petitionId=null;ui.roomDraftW=null;ui.roomDraftH=null;ui.questId=null;ui.memberId=null;ui.facilityId=null;ui.missionId=null;ui.selected.clear();syncUI();return;}if(d.pickMember){if(ui.selected.has(d.pickMember))ui.selected.delete(d.pickMember);else if(ui.selected.size<3)ui.selected.add(d.pickMember);else toast('หนึ่งทีมจัดได้ไม่เกินสามคน',true);syncUI();return;}if(d.policy){ui.policy=d.policy;syncUI();return;}if('sendMission'in d){if(dispatch('sendMission',{questId:ui.questId,memberIds:[...ui.selected],policy:ui.policy,petitionId:detailPetition()?.id})){ui.missionId=activeMissions().at(-1)?.id;ui.questId=null;ui.selected.clear();syncUI();}return;}if(d.eventChoice){dispatch('chooseEvent',{missionId:d.mission,choiceId:d.eventChoice});return;}if(d.recall){confirmAction('เรียกทีมกลับ?', 'ทีมจะหยุดภารกิจและกลับมาพักที่กิลด์',()=>dispatch('recallMission',{missionId:d.recall}));return;}if(d.recruit){dispatch('recruit',{memberId:d.recruit});return;}if(d.task){dispatch('setTask',{memberId:d.memberId,task:d.task});return;}if(d.build){cancelBuild();ui.buildType=d.build;ui.moveId=null;ui.facilityId=null;renderer?.setMoveMode(null);renderer?.setBuildMode(d.build);closeMenu();syncUI();return;}if(d.roomType){if(!$('room-width').reportValidity()||!$('room-height').reportValidity())return;const room={type:d.roomType,width:Number($('room-width').value),height:Number($('room-height').value),rotation:0};cancelBuild();ui.facilityId=null;ui.partitionId=null;ui.roomPlacement=room;renderer?.setRoomMode(room);closeMenu();syncHUD();return;}if(d.partition){ui.facilityId=null;ui.partitionId=d.partition;ui.roomDraftW=null;ui.roomDraftH=null;ui.tab='build';syncUI();return;}if(d.moveRoom){const room=state.rooms.find(r=>r.id===d.moveRoom);cancelBuild();ui.moveRoomId=room.id;renderer?.setRoomMode(room,room.id);closeMenu();syncHUD();return;}if(d.rotateRoom){dispatch('rotateRoom',{roomId:d.rotateRoom});return;}if(d.resizeRoom){const inputs=[...document.querySelectorAll('[data-partition-size]')];if(inputs.some(i=>!i.reportValidity()))return;dispatch('resizeRoom',{roomId:d.resizeRoom,width:Number(inputs.find(i=>i.dataset.partitionSize==='width').value),height:Number(inputs.find(i=>i.dataset.partitionSize==='height').value)});return;}if(d.demolishRoom){confirmAction('รื้อผนังห้อง?', 'ของภายในจะอยู่บนพื้นที่โล่ง ได้วัสดุคืนบางส่วน',()=>{if(dispatch('demolishRoom',{roomId:d.demolishRoom})){ui.partitionId=null;syncUI();}});return;}if('cancelBuild'in d){cancelBuild();return;}if(d.rotate){dispatch('rotate',{facilityId:d.rotate});return;}if('rotatePlacement'in d){renderer?.rotatePlacement();syncHUD();return;}if('expandBuilding'in d){confirmAction('ต่อเติมอาคาร?',moneyCost(getBuildingExpansionCost(state)),()=>dispatch('expandBuilding'));return;}if(d.move){cancelBuild();ui.moveId=d.move;ui.buildType=null;renderer?.setBuildMode(null);renderer?.setMoveMode(d.move);closeMenu();syncHUD();return;}if(d.upgrade){const f=state.facilities.find(f=>f.id===d.upgrade);const def=FACILITIES[f.type];const cost=getUpgradeCost(state,f.id);confirmAction('อัปเกรด'+def.name,`ปรับปรุงเป็นระดับ ${f.level+1} · ${moneyCost(cost)}`,()=>dispatch('upgrade',{facilityId:d.upgrade}));return;}if(d.demolish){confirmAction('รื้อของชิ้นนี้?', 'พื้นที่จะว่างให้จัดวางใหม่ ได้ทรัพยากรคืนบางส่วน ความจุและโบนัสจะลดลง',()=>{if(dispatch('demolish',{facilityId:d.demolish})){ui.facilityId=null;syncUI();}});return;}if('expand'in d){confirmAction('ขยายที่ดินกิลด์?',`${state.grid.width+6}×${state.grid.height+4} ช่อง · ${moneyCost(getExpansionCost(state))}`,()=>dispatch('expand'));return;}if(d.craft){dispatch('craft',{equipmentId:d.craft});return;}if(d.equip){const select=document.querySelector(`[data-equip-select="${CSS.escape(d.equip)}"]`);if(select)dispatch('equip',{memberId:select.value,equipmentId:d.equip});return;}if(d.unequip){dispatch('equip',{memberId:d.memberId,equipmentId:null,slot:d.unequip});return;}if(d.specialize){confirmAction('เปลี่ยนเป็น'+JOBS[d.specialize].name+'?', 'สมาชิกจะไปทำพิธีที่โรงฝึก (40 วินาที) ค่าพิธีจ่ายจากเงินส่วนตัวก่อน ขาดเท่าไรกิลด์ออกให้ · เลือกสายแล้วเปลี่ยนกลับไม่ได้',()=>dispatch('specialize',{memberId:d.memberId,classId:d.specialize}));return;}if(d.hostEvent){dispatch('hostEvent',{eventId:d.hostEvent});return;}if(d.speed){ui.speed=Number(d.speed);state.settings.speed=ui.speed;ui.paused=false;syncHUD();save();return;}if('dismissTutorial'in d){ui.tutorial=false;syncUI();return;}if('saveNow'in d){save(true);return;}if('exportSave'in d){const blob=new Blob([serializeGame(state)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`little-leaf-guild-day-${state.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ส่งออกไฟล์เซฟแล้ว');return;}if('importSave'in d){$('import-file').click();return;}if('toggleSound'in d){ui.sound=!ui.sound;state.settings.sound=ui.sound;save();playChime();b.textContent=ui.sound?'♪ เสียงเปิด':'♪ เสียงปิด';return;}if('newGame'in d){$('settings-dialog').close();confirmAction('เริ่มกิลด์ใหม่?', 'เซฟปัจจุบันจะถูกแทนที่ เริ่มจากบ้านว่างหลังแรก',()=>{closeMenu();showTitle();openSetup('new');});}});
$('pause-button').addEventListener('click',()=>{ui.paused=!ui.paused;syncHUD();});
$('zoom-in').addEventListener('click',()=>{ui.zoom=Math.min(2.4,(renderer?.zoom||1)+.15);renderer?.setZoom(ui.zoom);});$('zoom-out').addEventListener('click',()=>{ui.zoom=Math.max(.3,(renderer?.zoom||1)-.15);renderer?.setZoom(ui.zoom);});$('home-view').addEventListener('click',()=>{ui.zoom=1;renderer?.resetView?.();renderer?.setZoom(1);});
document.addEventListener('input',event=>{const d=event.target.dataset;if(d.roomDimension){ui[d.roomDimension==='width'?'roomWidth':'roomHeight']=Number(event.target.value);if($('room-estimate'))$('room-estimate').textContent=moneyCost(getPartitionCost(ui.roomWidth,ui.roomHeight));}if(d.partitionSize)ui[d.partitionSize==='width'?'roomDraftW':'roomDraftH']=Number(event.target.value);});
document.addEventListener('keydown',event=>{if(event.target.matches('input,select,textarea,button')||document.querySelector('dialog[open]'))return;if((event.key==='Enter'||event.key===' ')&&event.target.matches('[role="button"]')){event.preventDefault();event.target.click();return;}if(event.code==='KeyR'&&(ui.buildType||ui.moveId||ui.roomPlacement||ui.moveRoomId)){event.preventDefault();renderer?.rotatePlacement();syncHUD();return;}if(event.code==='Space'){event.preventDefault();ui.paused=!ui.paused;syncHUD();}if(['1','2','4'].includes(event.key)){ui.speed=Number(event.key);state.settings.speed=ui.speed;ui.paused=false;syncHUD();save();}if(event.key==='Escape'){cancelBuild();closeMenu();}});

// Goal card: always says what to do next, and opens the screen that does it.
function introGoal(){const step=state.intro.step,cost=type=>moneyCost(FACILITIES[type].cost);
 if(step==='reception')return{label:'บทนำ 1/5',title:'วางโต๊ะรับคำร้อง',meta:`ที่รับงานจากชาวบ้าน · แตะที่นี่แล้วแตะพื้นในบ้าน · ${cost('reception')}`,action:'build:reception',urgent:true};
 if(step==='dorm')return{label:'บทนำ 2/5',title:'วางเตียงพัก',meta:`นักผจญภัยจะอยู่ได้ต้องมีที่นอน · ${cost('dorm')}`,action:'build:dorm',urgent:true};
 if(step==='training')return{label:'บทนำ 3/5',title:'วางหุ่นฝึก',meta:`ให้มิราฝึกฝีมือ แล้วข่าวจะไปถึงคนอื่น · ${cost('training')}`,action:'build:training',urgent:true};
 if(step==='wait')return{label:'บทนำ',title:'รอคนมาเคาะประตู…',meta:'ข่าวว่ากิลด์เปิดแล้วกำลังแพร่ไปในหมู่บ้าน',progress:Math.min(1,state.intro.timer/(state.intro.delay||6)),action:'none'};
 if(step==='visit')return{label:'ก๊อก ก๊อก',title:'มีคนมาเคาะประตูกิลด์!',meta:'แตะเพื่อออกไปต้อนรับ',action:'visit',urgent:true};
 return null;}
function goalInfo(){if(introActive(state)){const g=introGoal();if(g)return g;}const stats=getGuildStats(state),missions=activeMissions(),pending=missions.find(m=>missionEventPending(m));
 const examining=state.members.find(m=>m.errand?.kind==='exam');
 if(examining&&!pending){const e=examining.errand;return{label:'กำลังสอบเลื่อนแรงค์',title:`${examining.name}กำลังสอบแรงค์ ${e.rank}`,meta:`ผลสอบออกในอีก ${Math.max(0,Math.ceil(e.end-state.elapsed))} วินาที · แตะเพื่อดู`,progress:Math.max(0,Math.min(1,(state.elapsed-e.start)/((e.end-e.start)||1))),action:'member:'+examining.id};}
 const ev=state.director?.pending;
 if(ev)return{label:ev.kind==='major'?'เหตุการณ์ใหญ่':'มีเรื่องให้ตัดสินใจ',title:`${ev.icon} ${ev.title}`,meta:`แตะเพื่อเลือก · ถ้าไม่ตอบใน ${Math.max(0,Math.ceil((ev.expires-state.elapsed)/60))} นาที จะเลือก “${ev.choices.at(-1)?.label||''}”`,action:'event',urgent:true};
 const found=state.trade?.treasures?.[0];
 if(found&&!ev)return{label:'เจอสมบัติ!',title:`${TREASURES[found.id].icon} ${TREASURES[found.id].name}`,meta:`${found.from?found.from+'นำมาขายให้กิลด์ · ':''}แตะเพื่อเลือกขายให้นักสะสมหรือจัดแสดง`,action:'trade',urgent:true};
 const big=state.director?.active;
 if(big&&!pending)return big.id==='raid'?{label:'เหตุการณ์ใหญ่',title:'🚨 มอนบุกหมู่บ้าน!',meta:`เหลือ ${(state.world?.monsters||[]).filter(m=>m.raid&&!m.dead).length} ตัว · บุกถึงกิลด์แล้ว ${big.reached||0} ตัว · แตะเพื่อดูการต่อสู้`,action:'watch:raid',urgent:true}:{label:'เหตุการณ์ใหญ่',title:'👑 บอสโลกปรากฏ!',meta:`ที่${HUNT_ZONES[big.zone]?.name||''} · นักผจญภัยแรงค์ถึงจะไปปราบเอง · แตะเพื่อดู`,action:'watch:boss',urgent:true};
 if(pending)return{label:'ตัดสินใจ',title:'ทีมเจอเหตุการณ์ระหว่างทาง',meta:'แตะเพื่อเลือกว่าทีมจะทำอย่างไร',action:'mission:'+pending.id,urgent:true};
 if(!state.completedQuests?.patrol){const m=missions.find(m=>m.questId==='patrol');
  if(m)return{label:'กำลังเดินทาง',title:'รอทีมลาดตระเวนกลับบ้าน',meta:`อีก ${Math.max(0,Math.ceil(m.duration-m.progress))} วินาที · กด ×4 เพื่อเร่งเวลา`,progress:missionRatio(m),action:'mission:'+m.id};
  if(missions.length)return{label:'กำลังเดินทาง',title:'รอทีมกลับบ้าน',meta:'แตะเพื่อดูทีม',progress:missionRatio(missions[0]),action:'mission:'+missions[0].id};
  return{label:introActive(state)?'บทนำ 4/5':'เริ่มที่นี่',title:'ส่งทีมลาดตระเวนครั้งแรก',meta:'แตะที่นี่ → เลือกสมาชิก หรือกด ⚡ ส่งอัตโนมัติ',action:'quest:patrol',urgent:true};}
 const waiting=(state.petitions||[]).filter(p=>p.status==='waiting'&&(p.important||state.policy?.autoPetitions===false));
 if(waiting.length)return{label:'ก๊อก ก๊อก',title:`${waiting[0].client}มาส่งคำร้อง`,meta:`${QUESTS.find(q=>q.id===waiting[0].questId)?.name||''} · ◈ ${n(waiting[0].fee)} G · แตะเพื่อรับหรือปฏิเสธ`,action:'quests',urgent:true};
  const door=(state.applicants||[]).find(a=>a.status==='waiting');
 if(door){const look=applicantLook(door);return{label:door.famous?'คนดังมาเยือน!':'มีคนมาสมัคร',title:`${look.name}อยากเข้าร่วมกิลด์`,meta:`${jobName(look.class)} Lv.${door.level} · ค่าแรกเข้า ${n(door.fee)} G · แตะเพื่อดู`,action:'members',urgent:true};}
 const examReady=state.members.map(m=>({m,r:getAdventurerRank(state,m)})).find(({m,r})=>r.eligible&&!m.errand&&!isAway(m.id)&&(m.purse||0)<r.rule.fee&&r.chance>=.4);
 if(examReady)return{label:'พร้อมสอบเลื่อนแรงค์',title:`${examReady.m.name}พร้อมสอบแรงค์ ${examReady.r.next}`,meta:`เงินส่วนตัวไม่พอค่าสอบ ${n(examReady.r.rule.fee)} G · โอกาสผ่าน ${Math.round(examReady.r.chance*100)}% · แตะเพื่อให้กิลด์ช่วยออก`,action:'member:'+examReady.m.id,urgent:true};
 if(!state.facilities.some(f=>f.type==='board'))return{label:'ปลดล็อกแล้ว',title:'วางกระดานคำร้อง',meta:`นักผจญภัยที่ว่างจะหยิบงานเอง · ${moneyCost(FACILITIES.board.cost)}`,action:'build:board'};
 if(state.story?.finished)return{label:'จบบทแรก (เดโม่)',title:'บ้านที่ทุกคนได้กลับมา',meta:'เล่นดูแลกิลด์และหมู่บ้านต่อได้ · ระดับ B จะเปิดในเกมเต็ม',action:'village'};
 if(state.rank!=='F'&&!state.facilities.some(f=>f.type==='dispatch'))return{label:'ปลดล็อกแล้ว',title:'วางโต๊ะวางแผน',meta:`ส่งได้สองทีมพร้อมกัน · ${moneyCost(FACILITIES.dispatch.cost)}`,action:'build'};
 const pr=getRankProgress(state);
 if(!pr||pr.future){const id=['mistpath','rescue','heart'].find(id=>!state.completedQuests?.[id]),q=QUESTS.find(q=>q.id===id),lock=getAvailableQuests(state).find(x=>x.id===id);return{label:'บทสุดท้ายของเดโม่',title:q?.name||'รักษาหัวใจป่า',meta:lock?.locked?lock.lockReason:'งานสำคัญที่ป่าหมอกจันทร์ · แตะเพื่อเลือกทีม',action:'quest:'+(id||'heart'),urgent:!lock?.locked&&!missions.length};}
 const exam=QUESTS.find(q=>q.id===pr.exam);
 if(pr.examReady&&!pr.examPassed)return{label:'สอบเลื่อนระดับ',title:`สอบเป็นกิลด์ ${pr.rank}: ${exam?.name||''}`,meta:'จดหมายจากสมาคมกิลด์มาถึงแล้ว · เลือกทีมที่พร้อมที่สุด',action:'quest:'+pr.exam,urgent:true};
 const missing=pr.merits.filter(m=>!m.ok),done=pr.merits.length-missing.length+(pr.rep>=pr.repNeeded?1:0),progress=done/(pr.merits.length+1);
 // Point the card at the menu that fixes the first missing merit, so nobody is left guessing where to go.
 const step=missing[0],how=step&&MERIT_HELP[step.kind];
 if(how)return{label:`เลื่อนเป็นกิลด์ ${pr.rank} · เหลือ ${missing.length+(pr.rep<pr.repNeeded?1:0)} ข้อ`,title:`${step.label} (${n(step.have)}/${n(step.need)})`,meta:how.meta,progress,action:how.action,coach:how.coach};
 return{label:'เป้าหมาย',title:`เลื่อนเป็นกิลด์ระดับ ${pr.rank}`,meta:[pr.rep<pr.repNeeded?`ชื่อเสียง ${n(pr.rep)}/${n(pr.repNeeded)}`:'ชื่อเสียงครบแล้ว',...missing.slice(0,2).map(m=>`${m.label} ${n(m.have)}/${n(m.need)}`)].join(' · '),progress,action:'quests'};}
const MERIT_HELP={
 village:{meta:'แตะเพื่อเปิดเมนู “หมู่บ้าน” ด้านล่าง · สร้างบ้านหรือร้านให้ชาวบ้าน และทำคำร้องให้ชาวบ้าน หมู่บ้านจะรุ่งเรืองขึ้น',action:'village',coach:'village'},
 members:{meta:'แตะเพื่อเปิดเมนู “สมาชิก” · รับคนที่มาสมัครหรือประกาศรับสมาชิกใหม่',action:'members',coach:'members'},
 ranked:{meta:'แตะเพื่อเปิดเมนู “สมาชิก” · ส่งสมาชิกที่พร้อมไปสอบเลื่อนแรงค์',action:'members',coach:'members'},
 classed:{meta:'แตะเพื่อเปิดเมนู “สมาชิก” · ให้สมาชิกเลื่อนอาชีพขั้นที่ 2',action:'members',coach:'members'},
 geared:{meta:'แตะเพื่อเปิดเมนู “คราฟต์” · ทำหรือมอบอาวุธให้สมาชิก',action:'workshop',coach:'workshop'},
 board:{meta:'แตะเพื่อวางกระดานคำร้องในกิลด์',action:'build:board'},
};
// Members go to their rank exams by themselves; the player is told when one starts and how it ended.
let examWatch=null;
function watchExams(){const now=new Map(state.members.filter(m=>m.errand?.kind==='exam').map(m=>[m.id,m.errand.rank])),open=id=>()=>{navigate('members');ui.memberId=id;syncUI();};
 if(examWatch){for(const [id,rank] of now)if(!examWatch.has(id)){const m=state.members.find(x=>x.id===id);toast(`${m.name}ไปสอบเลื่อนเป็นแรงค์ ${rank} ที่สนามสอบ · แตะเพื่อดู`,false,open(id));}
  for(const [id,rank] of examWatch)if(!now.has(id)){const m=state.members.find(x=>x.id===id);if(!m)continue;const passed=m.rank===rank;toast(passed?`${m.name}สอบผ่าน! เป็นนักผจญภัยแรงค์ ${rank}`:`${m.name}สอบแรงค์ ${rank} ไม่ผ่าน · จะกลับไปสอบใหม่พรุ่งนี้`,!passed,open(id));}}
 examWatch=now;}
function syncGoal(){watchExams();const g=goalInfo(),card=$('goal-card');if(!card)return;const html=`<small>${h(g.label)}</small><b>${h(g.title)}</b><span>${h(g.meta)}</span>${g.progress!=null?`<i class="goal-progress"><i style="width:${pct(g.progress,1)}%"></i></i>`:''}`;if(card.__html!==html){card.innerHTML=html;card.__html=html;}card.dataset.goal=g.action;card.classList.toggle('urgent',!!g.urgent);syncCoach(g.coach);}
// A pulsing hint on the dock button the current goal needs, until the player has opened that menu once for it.
let coachSeen=null;
function syncCoach(tab){if(!coachSeen){coachSeen={};try{coachSeen=JSON.parse(localStorage.getItem('guild-master:coach')||'{}');}catch{}}const seen=coachSeen;if(tab&&ui.tab===tab&&$('management-dialog').open){seen[tab]=true;try{localStorage.setItem('guild-master:coach',JSON.stringify(seen));}catch{}}
 for(const b of document.querySelectorAll('#dock .dock-btn')){const on=!!tab&&b.dataset.tab===tab&&!seen[tab];b.classList.toggle('coach',on);if(on)b.dataset.coachTip=tab==='village'?'พัฒนาหมู่บ้านที่นี่':tab==='members'?'ดูสมาชิกที่นี่':'เปิดที่นี่';}}
function runGoal(action){const[kind,id]=String(action).split(':');if(kind==='none')return;if(kind==='visit'){showVisitors();return;}if(kind==='event'){showEvent(true);return;}if(kind==='watch'){closeMenu();renderer?.startFollow('event',id);return;}cancelBuild();
 if(kind==='build'&&id){closeMenu();ui.buildType=id;ui.moveId=null;ui.facilityId=null;renderer?.setMoveMode(null);renderer?.setBuildMode(id);syncUI();return;}
 if(kind==='quest'){navigate('quests');const q=QUESTS.find(q=>q.id===id);if(q){ui.region=q.region;ui.questId=id;}syncUI();return;}
 if(kind==='member'&&id){navigate('members');ui.memberId=id;syncUI();return;}
 if(kind==='mission'){openMenu();ui.tab='quests';ui.missionId=id;ui.questId=null;syncUI();return;}
 navigate(['build','members','village','workshop','trade'].includes(kind)?kind:'quests');}
$('goal-card').addEventListener('click',()=>runGoal($('goal-card').dataset.goal));

// The storyteller: a choice opens a small dialog once; big events show a banner with a watch button.
let shownEvent=null;
function showEvent(force=false){const ev=state.director?.pending;if(!ev||$('event-dialog').open)return;if(!force&&(shownEvent===ev.expires+ev.id||$('management-dialog').open||$('report-dialog').open||$('visitor-dialog').open||$('confirm-dialog').open))return;shownEvent=ev.expires+ev.id;
 const left=Math.max(0,Math.ceil((ev.expires-state.elapsed)/60));
 $('event-content').innerHTML=`<small class="report-kicker">${ev.kind==='major'?'เหตุการณ์ใหญ่':'เรื่องที่ต้องตัดสินใจ'}</small><h2 id="event-title"><span class="event-big-icon">${h(ev.icon)}</span>${h(ev.title)}</h2><p>${h(ev.text)}</p><div class="event-choices">${ev.choices.map(c=>`<button class="event-choice" data-event-choice="${h(c.id)}"><b>${h(c.label)}</b><small>${h(c.desc)}</small></button>`).join('')}</div><div class="dialog-actions"><button class="secondary" data-event-later>ไว้ทีหลัง (${left} นาที)</button></div>`;
 $('event-dialog').showModal();}
$('event-dialog').addEventListener('click',event=>{const b=event.target.closest('[data-event-choice],[data-event-later]');if(!b)return;if(b.dataset.eventChoice){const ev=state.director?.pending;const r=act(state,'resolveEvent',{choiceId:b.dataset.eventChoice});if(r.ok){toast(`${ev?.icon||''} ${r.message}`);syncHUD();save();}else toast(r.message,true);}$('event-dialog').close();syncGoal();});
$('event-dialog').addEventListener('close',()=>{lastFrame=performance.now();});
let bannerKey=null;
function syncEventBanner(){const a=state.director?.alert,el=$('event-banner');const on=a&&a.until>state.elapsed;if(!on){if(!el.hidden)el.hidden=true;bannerKey=null;return;}const key=a.title+a.until;if(key===bannerKey)return;bannerKey=key;el.innerHTML=`<span class="event-big-icon">${h(a.icon)}</span><div><b>${h(a.title)}</b><small>${h(a.text)}</small></div>${a.watch?`<button type="button" data-watch-event="${h(a.watch)}">ดู</button>`:''}<button type="button" class="eb-close" aria-label="ปิด">✕</button>`;el.hidden=false;playChime();}
$('event-banner').addEventListener('click',event=>{const w=event.target.closest('[data-watch-event]');if(w){closeMenu();renderer?.startFollow('event',w.dataset.watchEvent);}if(event.target.closest('.eb-close,[data-watch-event]')){state.director.alert=null;syncEventBanner();}});

// Mission report: a clear payoff when a team comes home.
const reported=new Set(state.missions.filter(m=>m.status!=='active'&&m.status!=='decision').map(m=>m.id));const reportQueue=[];
function queueReports(before){for(const m of state.missions){if(reported.has(m.id)||m.status==='active'||m.status==='decision')continue;reported.add(m.id);if(m.auto&&!m.result?.loot?.some(e=>e.tier==='rare'||e.tier==='legendary')&&RANKS.indexOf(state.rank)===RANKS.indexOf(before.rank))continue;reportQueue.push({mission:m,before,rank:state.rank});}if(reportQueue.length&&!$('report-dialog').open)showReport();}
function showReport(){const r=reportQueue.shift();if(!r)return;const m=r.mission,q=QUESTS.find(q=>q.id===m.questId),res=m.result||{},rw=res.reward||{};
 const chips=[['gold','◈','G'],['wood','▰','ไม้'],['stone','◆','หิน'],['herb','❧','สมุนไพร'],['rep','★','ชื่อเสียง']].filter(([k])=>rw[k]>0).map(([k,icon,label])=>`<span class="report-chip"><b>${icon} +${n(rw[k])}</b><small>${label}</small></span>`).join('');
 const xp=Math.round((q?.reward?.xp||0)*(res.success?1:.35)),team=m.memberIds.map(id=>state.members.find(x=>x.id===id)).filter(Boolean).map(x=>{const up=x.level>(r.before.levels.get(x.id)||x.level);return `<div class="report-member ${up?'up':''}">${portrait(x)}<b>${h(x.name)}</b><small>${up?'เลเวลอัป! Lv.'+x.level:'Lv.'+x.level} · +${n(xp)} XP${x.injury>0?' · บาดเจ็บ':''}</small></div>`;}).join('');
 let rank='';if(RANKS.indexOf(r.rank)>RANKS.indexOf(r.before.rank)){const unlocked=[...(RANK_UNLOCKS[r.rank]||[])];rank=`<div class="report-rank"><span class="rank-seal">${h(r.rank)}</span><div><b>กิลด์เลื่อนเป็นระดับ ${h(r.rank)}!</b><small>${unlocked.length?'ปลดล็อก: '+h(unlocked.join(' · ')):'เปิดคำร้องและสิ่งปลูกสร้างใหม่'}</small></div></div>`;}
 const next=goalInfo();
 $('report-content').innerHTML=`<small class="report-kicker">${res.success?'ภารกิจสำเร็จ':'ทีมถอยกลับมา'} · ${h(q?.name||'')}</small><h2 id="report-title">${h(res.title||'ทีมกลับถึงบ้าน')}</h2><p>${h(res.message||'')}</p>${chips||res.wages?`<div class="report-chips">${chips}${res.wages?`<span class="report-chip"><b>👛 +${n(res.wages)}</b><small>ค่าจ้างทีม</small></span>`:''}</div>`:''}${lootFound(res.loot)}<div class="report-team">${team}</div>${rank}<div class="report-next"><small>ต่อไป</small><b>${h(next.title)}</b><span>${h(next.meta.replace(' · ทีมว่างอยู่ แตะเพื่อรับคำร้อง',''))}</span></div><div class="dialog-actions"><button class="secondary" data-report="close">กลับกิลด์</button><button class="primary" data-report="next">${next.action.startsWith('quest')||next.action==='quests'?'รับคำร้องต่อ':'ไปต่อ'}</button></div>`;
 injectIcons($('report-content'));$('report-dialog').showModal();}
$('report-dialog').addEventListener('click',event=>{const b=event.target.closest('[data-report]');if(!b)return;const go=b.dataset.report==='next';$('report-dialog').close();syncHUD();if(go)runGoal(goalInfo().action);});
$('report-dialog').addEventListener('close',()=>{lastFrame=performance.now();if(reportQueue.length)setTimeout(showReport,250);});

// Opening chapter: title screen, prologue and adventurers knocking at the door.
const VISITOR_LINES={get mira(){return `ได้ยินว่าบ้านข้างต้นโอ๊กเปิดเป็น${profile().guildName}แล้ว… คุณ${profile().masterName} ให้ฉันช่วยเฝ้าบ้านหลังนี้ได้ไหม`;},finn:'มิราเล่าว่ามีหุ่นฝึกแล้ว! ผมจำทางรอบหมู่บ้านได้หมดเลยนะ',lune:'ขอมาด้วยคนค่ะ อยากลองใช้เวทช่วยชาวบ้านดูบ้าง',noa:'ได้ยินว่าทีมแรกกลับมาอย่างปลอดภัย ถ้ามีใครบาดเจ็บ ฉันดูแลให้เองนะ'};
const VISITOR_NEXT={training:'ต่อไป: วางหุ่นฝึกให้มิราฝึกฝีมือ',patrol:'ครบทีมแล้ว! ส่งทีมลาดตระเวนครั้งแรกได้เลย',done:'สมาชิกครบสี่คนแล้ว ลองวางเตียงรักษาให้โนอาดูแลคนเจ็บ (เมนู → ห้องและต่อเติม)'};
function showVisitors(){if(!state.intro||state.intro.step!=='visit'||$('visitor-dialog').open)return;const ids=state.intro.visitors,people=ids.map(id=>MEMBERS.find(m=>m.id===id)).filter(Boolean);if(!people.length)return;
 $('visitor-content').innerHTML=`<small class="report-kicker">ก๊อก ก๊อก · มีคนมาที่ประตูกิลด์</small><h2 id="visitor-title">${people.length>1?h(people.map(p=>p.name).join(' และ '))+' มาขอเข้าร่วม':h(people[0].name)+' มาขอเข้าร่วมกิลด์'}</h2><div class="visitor-list">${people.map(p=>`<div class="visitor-card">${portrait(p)}<div><b>${h(p.name)}</b><small>${h(jobName(p.class))} · ${h(p.trait||'')}</small><p>“${h(VISITOR_LINES[p.id]||p.description)}”</p><span>${h(p.description)}</span></div></div>`).join('')}</div><div class="report-next"><small>ต่อไป</small><span>${h(VISITOR_NEXT[state.intro.after]||'')}</span></div><div class="dialog-actions"><button class="primary" data-welcome>ต้อนรับเข้ากิลด์</button></div>`;
 injectIcons($('visitor-content'));$('visitor-dialog').showModal();}
$('visitor-dialog').addEventListener('cancel',event=>event.preventDefault());
$('visitor-dialog').addEventListener('click',event=>{if(!event.target.closest('[data-welcome]'))return;const ids=[...(state.intro?.visitors||[])];renderer?.arrive?.(ids);$('visitor-dialog').close();if(dispatch('welcomeVisitors')){renderer?.resetView?.();}lastFrame=performance.now();});
const story=()=>{const p=profile();return[['จดหมายจากผู้ใหญ่บ้าน',`ถึงคุณ${p.masterName}`,'บ้านไม้ข้างต้นโอ๊กใหญ่ว่างมานาน ชาวบ้านอยากให้มีคนช่วยดูแลเส้นทางและป่ารอบหมู่บ้าน ช่วยเปิดบ้านหลังนี้เป็นกิลด์นักผจญภัยให้หน่อยได้ไหม'],['บ้านที่ยังว่างเปล่า',`${p.guildName} ยังไม่มีอะไรเลย`,'ไม่มีโต๊ะ ไม่มีเตียง และยังไม่มีนักผจญภัยสักคน ผู้ใหญ่บ้านฝากทุนตั้งต้นไว้ให้ 1,200 G พร้อมไม้และหินจำนวนหนึ่ง'],['หน้าที่ของหัวหน้ากิลด์',`${p.masterName} หัวหน้ากิลด์คนใหม่`,'กด “สร้าง” ที่แถบด้านล่างเพื่อวางของในบ้าน ต้อนรับนักผจญภัยที่มาเคาะประตู ส่งทีมไปรับคำร้อง แล้วพาทุกคนกลับบ้านอย่างปลอดภัย เริ่มจากวางโต๊ะรับคำร้องกันก่อน']];};
function showStory(page=0){const STORY=story(),[kicker,title,text]=STORY[page],last=page===STORY.length-1;$('story-content').innerHTML=`<div class="story-dots">${STORY.map((_,i)=>`<i class="${i===page?'on':''}"></i>`).join('')}</div><small class="report-kicker">${h(kicker)}</small><h2 id="story-title">${h(title)}</h2><p>${h(text)}</p><div class="dialog-actions">${last?'':'<button class="secondary" data-story-skip>ข้าม</button>'}<button class="primary" data-story-next="${page+1}">${last?'เริ่มเปิดกิลด์':'ต่อไป'}</button></div>`;if(!$('story-dialog').open)$('story-dialog').showModal();}
$('story-dialog').addEventListener('cancel',event=>event.preventDefault());
$('story-dialog').addEventListener('click',event=>{const b=event.target.closest('[data-story-next],[data-story-skip]');if(!b)return;const next=Number(b.dataset.storyNext);if(b.dataset.storySkip===undefined&&next<story().length){showStory(next);return;}$('story-dialog').close();lastFrame=performance.now();syncHUD();});
function startNewGame(profileDraft){state=createGame(Date.now()%100000+1,{opening:true,profile:profileDraft});hasSave=true;ui={...ui,tab:'quests',questId:null,memberId:null,facilityId:null,missionId:null,selected:new Set(),tutorial:true,paused:false,speed:1,sound:!!state.settings.sound};reported.clear();reportQueue.length=0;seenLog=state.log[0];cancelBuild();closeMenu();renderer?.setState(state);renderer?.resetView?.();save();syncUI();hideTitle();showStory(0);}
function showTitle(){document.body.classList.add('on-title');$('title-screen').hidden=false;$('title-continue').hidden=!hasSave;if(hasSave){$('title-save').textContent=`${profile().guildName} · `+(introActive(state)?`บทนำ · วันที่ ${n(state.day)}`:`วันที่ ${n(state.day)} · ระดับ ${state.rank} · สมาชิก ${state.members.length} คน`);}$('title-new').classList.toggle('primary',!hasSave);}
function hideTitle(){document.body.classList.remove('on-title');$('title-screen').hidden=true;lastFrame=performance.now();}
$('title-continue').addEventListener('click',()=>{hideTitle();playChime();});
// Hold the title buttons until the world has finished building, so a tap is never swallowed by a busy startup.
function titleBusy(busy){for(const id of ['title-continue','title-new'])$(id).disabled=busy;$('title-loading').hidden=!busy;}
if(renderer&&!renderer.ready){titleBusy(true);const started=Date.now(),wait=setInterval(()=>{if(renderer.ready||Date.now()-started>20000){clearInterval(wait);titleBusy(false);}},200);}
$('title-new').addEventListener('click',()=>{if(hasSave&&!(introActive(state)&&state.day===1&&!state.facilities.length)){confirmAction('เริ่มกิลด์ใหม่?','เซฟปัจจุบันจะถูกแทนที่ เริ่มจากบ้านว่างหลังแรก',()=>openSetup('new'));return;}openSetup('new');});

// Player identity: the guild master and the guild's name.
function profile(){return state.profile||DEFAULT_PROFILE;}
function masterSprite(p){return{id:'master',name:p.masterName,class:'master',hair:p.hair,outfit:p.outfit,skin:p.skin,hairStyle:p.hairStyle};}
function syncBrand(){const p=profile();if($('brand-name').textContent!==p.guildName)$('brand-name').textContent=p.guildName;const sub=state.profile?`หัวหน้ากิลด์ ${p.masterName}`:'LITTLE LEAF GUILD';if($('brand-sub').textContent!==sub)$('brand-sub').textContent=sub;const title=`Guild Master · R35`;if(document.title!==title)document.title=title;}
function guildTabs(){return `<div class="sheet-tabs"><button data-tab="home" class="${ui.tab==='home'?'active':''}">ภาพรวม</button><button data-tab="trade" class="${ui.tab==='trade'?'active':''}">การค้า${state.trade?.treasures?.length?' 💰':''}</button><button data-tab="journal" class="${ui.tab==='journal'?'active':''}">บันทึก</button><button data-tab="collection" class="${ui.tab==='collection'?'active':''}">สมุดสมบัติ</button><button data-edit-profile>หัวหน้ากิลด์</button><button data-guild-settings>เซฟ / ตั้งค่า</button></div>`;}
const NAME_IDEAS=['กิลด์ต้นกล้า','กิลด์ดาวเหนือ','กิลด์ชาอุ่น','กิลด์ต้นโอ๊ก','กิลด์หิ่งห้อย','กิลด์ขนมปังกรอบ'];
const LOOK_ROWS=[['hair','สีผม'],['outfit','สีชุด'],['skin','สีผิว']];
let setup=null;
function openSetup(mode){setup={mode,page:0,...normalizeProfile(mode==='edit'?profile():{masterName:'',guildName:''})};if(mode==='new'){setup.masterName='';setup.guildName='';}renderSetup();if(!$('setup-dialog').open)$('setup-dialog').showModal();}
function renderSetup(){const edit=setup.mode==='edit',first=setup.page===0;
 const look=LOOK_ROWS.map(([key,label])=>`<div class="look-row"><span>${label}</span><div>${PROFILE_LOOKS[key].map(c=>`<button class="swatch ${setup[key]===c?'on':''}" data-look="${key}" data-value="${c}" style="background:${c}" aria-label="${label} ${c}"></button>`).join('')}</div></div>`).join('')+`<div class="look-row"><span>ทรงผม</span><div>${[['short','สั้น'],['long','ยาว']].map(([v,l])=>`<button class="pill ${setup.hairStyle===v?'on':''}" data-look="hairStyle" data-value="${v}">${l}</button>`).join('')}</div></div>`;
 $('setup-content').innerHTML=first?`<small class="report-kicker">${edit?'แก้ไขหัวหน้ากิลด์':'สร้างหัวหน้ากิลด์ · 1/2'}</small><h2 id="setup-title">${edit?'หน้าตาและชื่อของคุณ':'หัวหน้ากิลด์คนใหม่คือคุณ'}</h2><div class="setup-master"><div class="setup-stage"><canvas id="setup-preview" width="96" height="96"></canvas><b id="setup-preview-name"></b></div><div class="setup-fields"><label class="setup-label">ชื่อหัวหน้ากิลด์<input id="setup-master" maxlength="20" placeholder="เช่น อาริน" value="${h(setup.masterName)}"></label>${look}</div></div><div class="dialog-actions"><button class="secondary" data-setup="${edit?'close':'back'}">${edit?'ยกเลิก':'กลับ'}</button><button class="primary" data-setup="next">${edit?'ต่อไป':'ต่อไป →'}</button></div>`
 :`<small class="report-kicker">${edit?'แก้ไขกิลด์':'ตั้งชื่อกิลด์ · 2/2'}</small><h2 id="setup-title">ตั้งชื่อกิลด์ของคุณ</h2><div class="guild-sign"><img src="${h(document.querySelector('.brand img')?.src||'')}" alt=""><b id="setup-sign"></b><small id="setup-sign-sub"></small></div><label class="setup-label">ชื่อกิลด์<input id="setup-guild" maxlength="20" placeholder="เช่น กิลด์ดาวเหนือ" value="${h(setup.guildName)}"></label><div class="name-ideas">${NAME_IDEAS.map(x=>`<button class="pill" data-name-idea="${h(x)}">${h(x)}</button>`).join('')}</div><div class="dialog-actions"><button class="secondary" data-setup="prev">← ย้อนกลับ</button><button class="primary" data-setup="done">${edit?'บันทึก':'เปิดกิลด์!'}</button></div>`;
 updateSetupPreview();}
function updateSetupPreview(){const p=normalizeProfile(setup);if($('setup-preview')){drawPortrait($('setup-preview'),masterSprite(p),96);$('setup-preview-name').textContent=setup.masterName.trim()||'(ยังไม่ตั้งชื่อ)';}if($('setup-sign')){$('setup-sign').textContent=setup.guildName.trim()||'ชื่อกิลด์';$('setup-sign-sub').textContent=`หัวหน้ากิลด์ ${p.masterName}`;}}
$('setup-dialog').addEventListener('input',event=>{if(event.target.id==='setup-master')setup.masterName=event.target.value;if(event.target.id==='setup-guild')setup.guildName=event.target.value;updateSetupPreview();});
$('setup-dialog').addEventListener('cancel',event=>{event.preventDefault();if(setup?.mode==='edit')$('setup-dialog').close();});
$('setup-dialog').addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.look){setup[d.look]=d.value;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));updateSetupPreview();return;}
 if(d.nameIdea){setup.guildName=d.nameIdea;$('setup-guild').value=d.nameIdea;updateSetupPreview();return;}
 if(d.setup==='back'){$('setup-dialog').close();return;}
 if(d.setup==='close'){$('setup-dialog').close();return;}
 if(d.setup==='next'){if(!setup.masterName.trim()){$('setup-master').focus();$('setup-master').classList.add('need');toast('ตั้งชื่อหัวหน้ากิลด์ก่อนนะ',true);return;}setup.page=1;renderSetup();return;}
 if(d.setup==='prev'){setup.page=0;renderSetup();return;}
 if(d.setup==='done'){if(!setup.guildName.trim()){$('setup-guild').focus();toast('ตั้งชื่อกิลด์ก่อนนะ',true);return;}const p=normalizeProfile(setup);$('setup-dialog').close();if(setup.mode==='edit'){dispatch('setProfile',p);return;}startNewGame(p);}});
document.addEventListener('click',event=>{const b=event.target.closest('[data-build-tab],[data-edit-profile],[data-guild-settings]');if(!b)return;if(b.dataset.buildTab){ui.buildTab=b.dataset.buildTab;syncUI();$('panel-content').scrollTop=0;return;}if('editProfile'in b.dataset){closeMenu();openSetup('edit');return;}if('guildSettings'in b.dataset)$('settings-button').click();});

// Dock: tapping the open section again closes the sheet; tapping the scene closes it too.
$('dock').addEventListener('click',event=>{const b=event.target.closest('[data-dock]');if(!b||!$('management-dialog').open)return;const group=['journal','collection'].includes(ui.tab)?'home':ui.tab;if(b.dataset.dock===group&&!ui.questId&&!ui.memberId&&!ui.facilityId&&!ui.missionId&&!ui.partitionId){event.stopPropagation();closeMenu();}},true);
$('world-wrap').addEventListener('pointerdown',()=>{if($('management-dialog').open)closeMenu();},true);
$('management-dialog').addEventListener('close',()=>document.body.classList.remove('sheet-open'));

// Placement bar: live validity from the renderer; nothing is placed until the player confirms.
function updatePlacementBar(info){if(!info?.active)return;const status=$('pb-status'),text=info.ok?'ลากของเพื่อย้าย · แตะพื้นเพื่อย้ายไปตรงนั้น':(info.message||'วางตรงนี้ไม่ได้');if(status.textContent!==text)status.textContent=text;status.classList.toggle('bad',!info.ok);$('build-hint').querySelector('[data-confirm-placement]').disabled=!info.ok;}
if(renderer)renderer.onPlacement=updatePlacementBar;
if(renderer)renderer.onVillagePick=info=>{const status=$('pb-status'),text=info.ok?'แตะพื้นที่ว่างรอบหมู่บ้านเพื่อย้ายจุดสร้าง':info.message;if(status.textContent!==text)status.textContent=text;status.classList.toggle('bad',!info.ok);$('build-hint').querySelector('[data-confirm-placement]').disabled=!info.ok;};
// Follow camera chip: who is being followed, a shortcut to their quest, and a stop button.
let followInfo=null;
function updateFollowChip(info){followInfo=info;$('follow-chip').hidden=!info;if(!info)return;$('fc-name').textContent=(info.kind==='event'?'ดู ':info.kind==='member'?'ติดตาม ':'ติดตามทีม ')+info.name;$('fc-sub').textContent=info.kind==='event'?(info.quest||''):info.quest?'ภารกิจ: '+info.quest:'อยู่ในกิลด์';$('fc-mission').hidden=!info.missionId;}
if(renderer)renderer.onFollow=updateFollowChip;
$('fc-stop').addEventListener('click',()=>renderer?.stopFollow());
$('fc-mission').addEventListener('click',()=>{if(followInfo?.missionId)onSceneSelect({kind:'mission',id:followInfo.missionId});});
document.addEventListener('click',event=>{if(!event.target.closest('[data-confirm-placement]'))return;if(ui.villagePlace){const v=renderer?.getVillagePick();if(!v)return;if(!v.ok){toast(v.message||'วางตรงนี้ไม่ได้',true);return;}const id=ui.villagePlace.projectId;if(dispatch('buildProject',{projectId:id,spot:{x:v.x,y:v.y}})){ui.villagePlace=null;renderer.stopVillagePlacement();renderer.setState(state);syncUI();}return;}const p=renderer?.getPlacement();if(!p?.active)return;if(!p.ok){toast(p.message||'วางตรงนี้ไม่ได้',true);return;}onSceneSelect({kind:p.kind,x:p.x,y:p.y,rotation:p.rotation,facilityId:p.facilityId,roomId:p.roomId});});

// Chest loot: what a quest can give, the team's luck, and what was found.
function lootLabel(entry){return entry.kind==='mat'?`${({gold:'เงิน',wood:'ไม้',stone:'หิน',herb:'สมุนไพร'})[entry.key]} +${entry.amount!=null?n(entry.amount):n(entry.min)+'–'+n(entry.max)}`:item(entry.id)?.name||entry.id;}
function lootIcon(entry){return itemIcon(entry.kind==='mat'?({gold:'coin',wood:'wood',stone:'stone',herb:'herb'})[entry.key]:entry.id);}
function lootPreview(q){const table=LOOT[q.id];if(!table)return'';return `<div class="section-title">ของที่อาจได้จากหีบ<small>3 หีบต่อการเดินทาง</small></div><div class="loot-table">${['legendary','rare','uncommon','common'].map(tier=>(table[tier]||[]).map(e=>{const known=e.kind==='mat'||tier!=='legendary'||inventoryCount(e.id)>0;return `<span class="loot ${tier}">${known?lootIcon(e):'<b>?</b>'}<small>${known?h(lootLabel(e)):'สมบัติลึกลับ'}</small><i>${h(RARITIES[tier].name)}</i></span>`;}).join('')).join('')}</div>`;}
function luckStars(luck=0){const k=Math.round(Math.min(.45,luck)/.45*5);return '★'.repeat(k)+'<i>'+'★'.repeat(5-k)+'</i>';}
function lootFound(loot=[]){return loot.length?`<div class="report-loot"><small>สมบัติที่พบ</small><div>${loot.map(e=>`<span class="loot ${e.tier}">${lootIcon(e)}<small>${h(lootLabel(e))}</small><i>${h(RARITIES[e.tier].name)}</i></span>`).join('')}</div></div>`:'';}

// Automatic dispatch: the best rested team for a quest, or the most useful quest for the board button.
function autoQuest(){const stats=getGuildStats(state);if(stats.activeMissions>=stats.teamCap)return null;const quests=getAvailableQuests(state),order=p=>(p.important?1000:0)+p.fee;
 for(const p of (state.petitions||[]).filter(p=>p.status==='posted'&&!p.missionId).sort((a,b)=>order(b)-order(a))){const q=quests.find(q=>q.id===p.questId);if(!q||q.locked)continue;const team=suggestTeam(state,q.id,'balanced'),pv=previewMission(state,q.id,team,'balanced');if(pv.ok&&pv.readiness>=.95)return{quest:q,team,petition:p};}return null;}
function sendTeam(questId,team,policy,petitionId){if(!team.length){toast('ยังไม่มีสมาชิกที่พร้อมเดินทาง',true);return;}if(dispatch('sendMission',{questId,memberIds:team,policy,petitionId})){ui.petitionId=null;ui.missionId=activeMissions().at(-1)?.id;ui.questId=null;ui.selected.clear();syncUI();}}
function renderCollection(){const treasures=EQUIPMENT.filter(e=>e.loot),found=e=>inventoryCount(e.id)>0||state.members.some(m=>Object.values(m.equipment||{}).includes(e.id))||(state.foundTreasures||[]).includes(e.id);const where=id=>Object.entries(LOOT).filter(([,t])=>Object.values(t).flat().some(x=>x.id===id)).map(([q])=>QUESTS.find(x=>x.id===q)?.name).filter(Boolean);
 const got=treasures.filter(found).length;return `<div class="collection-head"><b>${got}/${treasures.length}</b><small>สมบัติที่ค้นพบ</small><div class="progress"><i style="width:${pct(got/treasures.length,1)}%"></i></div></div><div class="collection">${treasures.map(e=>{const ok=found(e);return `<div class="loot ${e.rarity} ${ok?'':'unknown'}">${ok?itemIcon(e.id):'<b>?</b>'}<small>${ok?h(e.name):'ยังไม่ค้นพบ'}</small><i>${h(RARITIES[e.rarity].name)}</i><em>${h(ok?e.description:'พบได้ที่: '+where(e.id).slice(0,2).join(', '))}</em></div>`;}).join('')}</div>`;}
document.addEventListener('click',event=>{const b=event.target.closest('[data-auto-team],[data-auto-send],[data-auto-board],[data-auto-equip],[data-sell]');if(!b||b.disabled)return;const d=b.dataset;
 if('autoTeam'in d||'autoSend'in d){const team=suggestTeam(state,ui.questId,ui.policy);if('autoSend'in d){sendTeam(ui.questId,team,ui.policy,detailPetition()?.id);return;}ui.selected=new Set(team);if(!team.length)toast('ยังไม่มีสมาชิกที่พร้อมเดินทาง',true);syncUI();return;}
 if('autoBoard'in d){const auto=autoQuest();if(auto)sendTeam(auto.quest.id,auto.team,'balanced',auto.petition.id);return;}
 if('autoEquip'in d){dispatch('autoEquip');return;}
 if(d.sell){const e=item(d.sell);confirmAction(`ขาย${e.name}?`,`ได้ ${n(getSellPrice(d.sell))} G · ขายแล้วเอาคืนไม่ได้`,()=>dispatch('sellItem',{equipmentId:d.sell}));}});


document.addEventListener('click',event=>{const b=event.target.closest('[data-watch-mission]');if(!b)return;closeMenu();renderer?.focusMission(b.dataset.watchMission);});
let lastFrame=performance.now(),uiTimer=0,saveTimer=0,seenLog=state.log[0];
function frame(now){state.settings.paused=ui.paused;const dt=Math.max(0,Math.min((now-lastFrame)/1000,.25));lastFrame=now;if(renderer?.ready&&!document.hidden&&!ui.paused&&!$('confirm-dialog').open&&!$('settings-dialog').open&&!$('report-dialog').open&&!$('event-dialog').open&&!$('visitor-dialog').open&&!$('story-dialog').open&&!$('setup-dialog').open&&$('title-screen').hidden){const before={rank:state.rank,levels:new Map(state.members.map(m=>[m.id,m.level]))};tick(state,dt*ui.speed);queueReports(before);if(state.intro?.step==='visit'&&!$('report-dialog').open&&!$('management-dialog').open)showVisitors();showEvent();syncEventBanner();renderer?.setState(state);uiTimer+=dt;saveTimer+=dt;if(state.log[0]!==seenLog){const latest=state.log[0];if(latest?.type!=='daily'){if(!/ไปสอบเลื่อนเป็นแรงค์|สอบผ่าน! เลื่อนเป็นนักผจญภัย|สอบแรงค์ \S+ ไม่ผ่าน/.test(latest.text))toast(latest.text);playChime();}seenLog=state.log[0];}if(uiTimer>.9){syncHUD();if(!document.activeElement?.matches('input,select,textarea')&&(ui.missionId||ui.questId||ui.tab==='journal'||ui.tab==='trade'||ui.tab==='members'||ui.tab==='build'||ui.tab==='workshop'))syncUI();uiTimer=0;}if(saveTimer>12){save();saveTimer=0;}}if(ui.missionId)drawMissionScene();requestAnimationFrame(frame);}
function drawMissionScene(){const canvas=$('mission-scene');if(!canvas||!ui.missionId)return;const mission=state.missions.find(m=>m.id===ui.missionId);const quest=QUESTS.find(q=>q.id===mission?.questId);if(mission&&quest)drawDungeonScene(canvas,mission,quest,state,{paused:ui.paused||document.hidden||!$('management-dialog').open,time:performance.now()/1000,eventPending:missionEventPending(mission)});}

syncUI();injectIcons($('dock'));if(hasSave)save();showTitle();requestAnimationFrame(frame);if(loadNotice)setTimeout(()=>toast(loadNotice,true),800);if(idleNotice)setTimeout(()=>toast(idleNotice),1300);document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();if(document.hidden)save();});window.addEventListener('pagehide',()=>save());
// Read-only diagnostics, useful for reproducible bug reports without a cheat menu.
window.guildDebug={focusGrid:(x,y,z)=>renderer?.focusGrid(x,y,z),getState:()=>JSON.parse(serializeGame(state)),getScenePoint:(x,y)=>{const r=renderer.worldToScreen(x*32,y*32),b=$('guild-world').getBoundingClientRect();return{x:b.left+r.x*b.width/renderer.width,y:b.top+r.y*b.height/renderer.height};},getRendererInfo:()=>renderer?.getInfo(),getTravellers:()=>{const b=$('guild-world').getBoundingClientRect();return(renderer?.travellerPoints()||[]).map(t=>({...t,x:b.left+t.x*b.width/renderer.width,y:b.top+t.y*b.height/renderer.height}));},getSnapshot:()=>({rank:state.rank,day:state.day,members:state.members.length,quests:state.completedQuests,finished:state.story?.finished})};
